insert into curriculum_topics values ('N1-social-habits-t1-w4','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'4',4,'teaching',null,'Simple Courtesy: Saying "I Am Sorry"','["When to say \"I am sorry\"", "Why we apologize", "Making things right", "Forgiveness"]'::jsonb,'[]'::jsonb,'["Teaching \"I Am Sorry\":", "The teacher explains \"I am sorry\" is what we say when we make a mistake or hurt someone", "The teacher demonstrates apologizing sincerely", "The teacher lists situations: when we hurt someone, break something, make someone sad, do something wrong", "The teacher emphasizes meaning it when we say it. When to Apologize:", "The teacher gives examples: pushing someone, taking someone''s toy, saying mean words, not sharing, breaking something", "The teacher role-plays apology scenarios with puppets", "The teacher demonstrates saying \"I am sorry\" and making amends", "The teacher introduces \"It''s okay\" or \"I forgive you\" as responses. Making Amends:", "The teacher explains saying sorry should be followed by being nice", "The teacher discusses not repeating the same mistake", "The teacher teaches about forgiveness when someone says sorry to us", "The teacher reads stories about saying sorry and forgiveness", "The teacher prepares pupils for mid-term assessment"]'::jsonb,'["Learning \"I Am Sorry\":", "Pupils understand when they should say \"I am sorry\"", "Pupils watch apology demonstrations", "Pupils learn situations requiring apologies", "Pupils understand sincerity matters. Practice:", "Pupils identify when \"sorry\" is needed", "Pupils watch apology role-plays", "Pupils practice saying \"I am sorry\"", "Pupils learn to respond \"It''s okay\" Understanding:", "Pupils understand sorry means trying to be better", "Pupils learn not to repeat mistakes", "Pupils learn to forgive others", "Pupils listen to forgiveness stories", "Pupils prepare for mid-term test"]'::jsonb,'["Puppets", "Role-play materials", "Story books about apologies", "Pictures of apologizing", "Forgiveness chart", "Sorry/forgiveness cards"]'::jsonb,264) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t1-w5','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'5',5,'midterm_assessment',null,'Mid-term Assessment/t Est','[]'::jsonb,'[]'::jsonb,'["Assessment Activities:", "The teacher administers mid-term assessment on social habits", "The teacher tests self-awareness: pupils state their names and ages", "The teacher assesses greeting skills: pupils demonstrate appropriate greetings for different times", "The teacher tests \"Thank you\": pupils identify situations and practice saying it", "The teacher assesses \"I am sorry\": pupils identify when to apologize", "The teacher evaluates courtesy and politeness in interactions", "The teacher uses role-play, oral questions, and observation", "The teacher records pupils'' social behavior and courtesy skills"]'::jsonb,'["Assessment Tasks:", "Pupils state their full names and ages clearly", "Pupils greet teacher appropriately (\"Good morning/afternoon\")", "Pupils demonstrate saying \"Thank you\" in given scenarios", "Pupils show when to say \"I am sorry\"", "Pupils participate in courtesy role-plays", "Pupils demonstrate polite behavior", "Pupils interact courteously with teacher and classmates", "Pupils show understanding of courtesy topics covered"]'::jsonb,'["Assessment checklist", "Role-play scenarios", "Observation forms", "Courtesy cards", "Mark book", "Assessment materials"]'::jsonb,265) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t1-w6','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,266) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t1-w7','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'7',7,'teaching',null,'My Family','["Identifying members of the family", "Father, Mother, Brother, Sister", "Grandparents", "Family love"]'::jsonb,'[]'::jsonb,'["Introduction to Family:", "The teacher explains what a family is: people who live together and love each other", "The teacher shows pictures of different families", "The teacher discusses immediate family members: father, mother, siblings", "The teacher uses family tree diagrams (simple). Family Members:", "The teacher identifies and names family members: father/daddy, mother/mummy, brother, sister, grandfather/grandpa, grandmother/grand ma", "The teacher shows pictures and asks pupils to identify family members", "The teacher asks pupils to talk about their own families", "The teacher discusses that families can be different sizes. Family Love:", "The teacher emphasizes families love and care for each other", "The teacher discusses what families do together", "The teacher encourages pupils to draw their families", "The teacher sings family songs (\"Finger Family\")", "The teacher reads family story books"]'::jsonb,'["Learning About Family:", "Pupils understand what a family is", "Pupils observe pictures of families", "Pupils learn about immediate family members", "Pupils look at simple family trees. Identifying Members:", "Pupils learn names of family members: father, mother, brother, sister, grandparents", "Pupils identify family members in pictures", "Pupils talk about their own families", "Pupils understand families are different. Understanding:", "Pupils understand families love each other", "Pupils share what they do with families", "Pupils draw pictures of their families", "Pupils sing \"Finger Family\" song", "Pupils listen to family stories"]'::jsonb,'["Family pictures", "Family tree chart", "Drawing paper", "Crayons", "Family story books", "Finger family props", "Song charts", "Photos of different families"]'::jsonb,266) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t1-w8','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'8',8,'teaching',null,'MY FAMILY (Continued)','["Extended family", "Uncles, Aunts, Cousins", "Family gatherings", "Respect for family members"]'::jsonb,'[]'::jsonb,'["Extended Family:", "The teacher introduces extended family: uncles, aunts, cousins", "The teacher explains these are relatives we see at gatherings", "The teacher shows pictures of extended family structures", "The teacher discusses how extended family supports us. Family Relationships:", "The teacher explains: uncle is father''s or mother''s brother, aunt is father''s or mother''s sister, cousins are uncle''s or aunt''s children", "The teacher uses simple relationship diagrams", "The teacher asks pupils to share about their relatives. Family Gatherings:", "The teacher discusses family gatherings: parties, celebrations, holidays, visits", "The teacher talks about activities at family events", "The teacher emphasizes being respectful to all family members, especially elders", "The teacher teaches greeting relatives properly", "The teacher encourages sharing family photos (if brought)"]'::jsonb,'["Extended Family:", "Pupils learn about uncles, aunts, cousins", "Pupils understand these are relatives", "Pupils observe extended family pictures", "Pupils learn family helps each other. Relationships:", "Pupils understand basic family relationships", "Pupils see relationship diagrams", "Pupils talk about their relatives. Gatherings:", "Pupils discuss family gatherings they''ve attended", "Pupils share what happens at family events", "Pupils learn to respect family members, especially elders", "Pupils practice greeting relatives", "Pupils share family photos (if available)"]'::jsonb,'["Extended family pictures", "Family relationship chart", "Photos of family gatherings", "Drawing materials", "Pupils'' family photos", "Story books about families"]'::jsonb,268) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t1-w9','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'9',9,'teaching',null,'Roles of Members of the Family','["What father does", "What mother does", "What children do", "Helping at home"]'::jsonb,'[]'::jsonb,'["Father''s Role:", "The teacher discusses what fathers do: work to provide money, protect family, play with children, teach us, love us", "The teacher shows pictures of fathers at work and with families", "The teacher encourages pupils to share what their fathers do. Mother''s Role:", "The teacher discusses what mothers do: cook food, take care of children, work, clean house, teach us, love us", "The teacher shows pictures of mothers doing various activities", "The teacher emphasizes both parents work hard for the family. Children''s Role:", "The teacher discusses what children can do: be obedient, help with small chores, love parents, be respectful, do well in school", "The teacher emphasizes children should help at home", "The teacher lists simple chores: putting toys away, helping set table, tidying room. Family Cooperation:", "The teacher explains families work together", "The teacher discusses everyone has a role in making home happy", "The teacher encourages appreciation for what parents do", "The teacher role-plays family scenarios"]'::jsonb,'["Father''s Role:", "Pupils learn what fathers do for families", "Pupils observe pictures of fathers", "Pupils share about their fathers. Mother''s Role:", "Pupils learn what mothers do for families", "Pupils observe pictures of mothers", "Pupils understand both parents work hard. Children''s Role:", "Pupils understand they can help at home too", "Pupils learn to be obedient and respectful", "Pupils identify simple chores they can do. Cooperation:", "Pupils understand families work together", "Pupils learn everyone contributes to family happiness", "Pupils appreciate what parents do", "Pupils participate in family role-plays"]'::jsonb,'["Pictures of fathers at work", "Pictures of mothers", "Pictures of children helping", "Family roles chart", "Role-play props", "Story books about family cooperation"]'::jsonb,269) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t1-w10','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'10',10,'teaching',null,'Activities at Home and in School & School Awareness','["Activities at home", "Activities at school", "Knowing school name", "Knowing teachers'' and friends'' names"]'::jsonb,'[]'::jsonb,'["Activities at Home:", "The teacher discusses things we do at home: eating, sleeping, playing, watching TV, helping parents, bathing", "The teacher compares weekday and weekend activities", "The teacher asks pupils to share their home activities. Activities at School:", "The teacher discusses things we do at school: learning, playing, singing, eating snacks, making friends, listening to teacher", "The teacher compares home and school activities", "The teacher emphasizes school is for learning. School Awareness:", "The teacher teaches pupils the name of their school and helps them repeat it", "The teacher shows the school sign/logo", "The teacher reviews all teachers'' names and helps pupils remember them", "The teacher conducts name recognition activities for classmates", "The teacher emphasizes we are part of school family. School Pride:", "The teacher teaches school anthem/song (if any)", "The teacher discusses loving and taking care of school", "The teacher prepares pupils for revision week"]'::jsonb,'["Home Activities:", "Pupils learn about daily home activities", "Pupils compare weekday and weekend", "Pupils share what they do at home. School Activities:", "Pupils identify school activities", "Pupils understand differences between home and school", "Pupils know school is for learning. School Awareness:", "Pupils learn and say their school name", "Pupils identify school sign/logo", "Pupils know and can name their teachers", "Pupils recognize classmates'' names", "Pupils feel part of school family. School Pride:", "Pupils learn school song", "Pupils understand importance of caring for school", "Pupils prepare for revision"]'::jsonb,'["Pictures of home activities", "Pictures of school activities", "School sign/logo", "Teachers'' name cards", "Pupils'' name tags", "School anthem/song chart", "Comparison chart"]'::jsonb,270) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t1-w11','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'11',11,'revision',null,'REVISION OF FIRST TERM WORK All social habits topics','[]'::jsonb,'[]'::jsonb,'["Comprehensive Revision:", "The teacher systematically reviews self-awareness: naming self, stating age", "The teacher revises all courtesy phrases: greetings (Good morning, afternoon, evening, Hello, Hi), \"Thank you,\" \"I am sorry\"", "The teacher reviews family: immediate family members, extended family, roles of family members", "The teacher revises activities at home and school", "The teacher reviews school awareness: school name, teachers'' names, friends'' names", "The teacher uses role-plays, games, songs for revision", "The teacher conducts mock assessment activities", "The teacher reinforces polite behavior and good manners", "The teacher identifies areas needing extra support", "The teacher builds confidence for final examination"]'::jsonb,'["Revision Activities:", "Pupils state their names and ages confidently", "Pupils practice all courtesy phrases: greetings, \"Thank you,\" \"I am sorry\"", "Pupils identify and name family members and their roles", "Pupils discuss home and school activities", "Pupils state school name and teachers'' names", "Pupils participate enthusiastically in revision games and role-plays", "Pupils complete mock assessment tasks", "Pupils demonstrate polite, courteous behavior", "Pupils ask questions about difficult areas", "Pupils show readiness for examination"]'::jsonb,'["All term''s materials", "Family pictures", "Courtesy charts", "Role-play props", "Name cards", "School materials", "Revision worksheets", "Mock test materials", "Games"]'::jsonb,272) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t1-w12','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'12',12,'examination',null,'End of Term Examination','[]'::jsonb,'[]'::jsonb,'["Examination Administration:", "The teacher administers comprehensive end-of-term social habits examination", "The teacher tests self-awareness: pupils state names, ages clearly", "The teacher assesses greetings: pupils greet appropriately for different times of day", "The teacher tests courtesy: pupils demonstrate \"Thank you\" and \"I am sorry\" in scenarios", "The teacher assesses family knowledge: pupils name family members and their roles", "The teacher tests knowledge of home and school activities", "The teacher assesses school awareness: pupils state school name, identify teachers and friends", "The teacher evaluates overall courtesy, politeness, and social behavior", "The teacher uses oral questions, role-plays, and practical demonstrations", "The teacher marks and prepares report cards with behavior comments"]'::jsonb,'["Examination Tasks:", "Pupils state their full names and ages", "Pupils demonstrate appropriate greetings", "Pupils show when and how to say \"Thank you\" and \"I am sorry\"", "Pupils identify family members in pictures and explain their roles", "Pupils discuss activities at home and school", "Pupils state their school name and name teachers", "Pupils demonstrate polite, courteous behavior throughout examination", "Pupils participate in all role-play scenarios", "Pupils answer oral questions", "Pupils show complete understanding of first term social habits"]'::jsonb,'["Examination materials", "Family pictures", "Courtesy scenario cards", "Role-play props", "School materials", "Assessment checklist", "Observation forms", "Mark book", "Report cards"]'::jsonb,273) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t1-w13','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'13',13,'closing',null,'Closing & End of Term Activities','[]'::jsonb,'[]'::jsonb,'["Closing Activities:", "The teacher returns marked work with positive feedback", "The teacher discusses individual behavior and social development", "The teacher celebrates pupils'' courtesy and good manners", "The teacher awards certificates for exemplary behavior", "The teacher distributes report cards", "The teacher provides holiday tips: continue practicing courtesy at home, help parents, be respectful", "The teacher gives preview of second term topics", "The teacher encourages continued good behavior during holidays"]'::jsonb,'["Closing Activities:", "Pupils receive marked work and report cards", "Pupils listen to behavior feedback", "Pupils celebrate their social development", "Pupils receive behavior awards/certificates", "Pupils get holiday courtesy reminders", "Pupils look forward to second term", "Pupils say polite goodbyes to teachers and friends"]'::jsonb,'["Report cards", "Marked work", "Behavior certificates", "Awards", "Holiday behavior tips sheets", "Celebration materials"]'::jsonb,274) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t2-w1','ng-scheme-2025-preprimary-primary','N1','social-habits',2,'1',1,'teaching',null,'Personal Hygiene','["Importance of cleanliness", "Washing hands", "Bathing daily", "Brushing teeth"]'::jsonb,'[]'::jsonb,'["Introduction to Hygiene:", "The teacher welcomes pupils back and reviews first term courtesy briefly", "The teacher introduces personal hygiene: keeping our bodies clean", "The teacher explains cleanliness keeps us healthy and makes us look good", "The teacher discusses when we need to be clean. Hand Washing:", "The teacher demonstrates proper handwashing with soap and water", "The teacher explains when to wash hands: before eating, after toilet, after playing, when dirty", "The teacher teaches handwashing steps: wet hands, apply soap, scrub all parts, rinse, dry", "The teacher supervises practical handwashing activities. Other Hygiene Practices:", "The teacher emphasizes bathing every day to stay clean and smell nice", "The teacher reviews tooth brushing from first term (pre-science)", "The teacher discusses wearing clean clothes", "The teacher sings hygiene songs"]'::jsonb,'["Learning Hygiene:", "Pupils understand importance of being clean", "Pupils learn keeping clean makes us healthy", "Pupils know cleanliness makes us look and feel good. Hand Washing:", "Pupils watch handwashing demonstration", "Pupils learn when to wash hands", "Pupils learn handwashing steps", "Pupils practice washing hands properly. Other Practices:", "Pupils understand importance of daily baths", "Pupils recall tooth brushing importance", "Pupils understand wearing clean clothes", "Pupils sing hygiene songs"]'::jsonb,'["Hand washing station", "Soap", "Water", "Towels", "Hygiene charts", "Pictures of clean children", "Song charts", "Demonstration materials"]'::jsonb,276) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t2-w2','ng-scheme-2025-preprimary-primary','N1','social-habits',2,'2',2,'teaching',null,'Cleanliness and Tidiness','["Keeping our environment clean", "Proper waste disposal", "Tidying up toys and books", "Clean classroom"]'::jsonb,'[]'::jsonb,'["Environmental Cleanliness:", "The teacher explains keeping our surroundings clean is important", "The teacher discusses clean environments: classroom, home, school compound", "The teacher demonstrates picking up litter and putting in bin", "The teacher emphasizes not littering. Waste Disposal:", "The teacher shows proper use of waste bins/trash cans", "The teacher demonstrates disposing of paper, food wrappers, etc", "The teacher teaches \"don''t throw things on the floor\"", "The teacher organizes classroom clean-up activities. Tidiness:", "The teacher teaches putting toys back after playing", "The teacher demonstrates organizing books on shelves", "The teacher emphasizes keeping personal space tidy", "The teacher assigns simple classroom tidying duties", "The teacher rewards tidiness and cleanliness"]'::jsonb,'["Learning Cleanliness:", "Pupils understand importance of clean environment", "Pupils learn about clean spaces", "Pupils watch litter disposal demonstration", "Pupils learn not to litter. Waste Disposal:", "Pupils learn to use waste bins properly", "Pupils practice disposing waste correctly", "Pupils understand not to throw things on floor", "Pupils participate in clean-up activities. Tidiness:", "Pupils learn to put toys away after use", "Pupils organize books properly", "Pupils keep their spaces tidy", "Pupils help with classroom tidying", "Pupils enjoy being clean and tidy"]'::jsonb,'["Waste bins", "Cleaning materials", "Toys", "Books", "Tidiness charts", "Before/after pictures", "Reward stickers", "Cleaning tools (child-safe)"]'::jsonb,277) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t2-w3','ng-scheme-2025-preprimary-primary','N1','social-habits',2,'3',3,'teaching',null,'Sharing and Caring','["Importance of sharing", "Sharing toys and books", "Caring for others", "Being kind"]'::jsonb,'[]'::jsonb,'["Introduction to Sharing:", "The teacher explains sharing means letting others use what we have", "The teacher demonstrates sharing toys with classmates", "The teacher discusses why sharing is important: makes friends, makes others happy, shows kindness", "The teacher reads stories about sharing. Practice Sharing:", "The teacher organizes sharing activities with classroom toys and books", "The teacher teaches taking turns when sharing", "The teacher demonstrates asking politely to share: \"Can I share with you?\"", "The teacher addresses difficulties in sharing and encourages generosity. Caring for Others:", "The teacher explains caring means showing love and concern for others", "The teacher demonstrates helping someone who falls or is sad", "The teacher teaches checking on friends who are absent or unwell", "The teacher emphasizes being kind to everyone", "The teacher rewards sharing and caring behavior"]'::jsonb,'["Learning Sharing:", "Pupils understand what sharing means", "Pupils watch sharing demonstrations", "Pupils learn why sharing is important", "Pupils listen to sharing stories. Practice:", "Pupils share toys and books with classmates", "Pupils learn to take turns", "Pupils ask politely to share", "Pupils try to be generous with their things. Caring:", "Pupils understand caring means showing concern", "Pupils help friends who need assistance", "Pupils show concern for absent or unwell classmates", "Pupils practice kindness to everyone", "Pupils enjoy being caring and sharing"]'::jsonb,'["Toys for sharing", "Books", "Story books about sharing", "Sharing chart", "Reward stickers", "Pictures of children sharing", "Role-play props"]'::jsonb,278) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t2-w4','ng-scheme-2025-preprimary-primary','N1','social-habits',2,'4',4,'teaching',null,'Good Eating Habits','["Eating properly", "Table manners", "Not wasting food", "Healthy eating"]'::jsonb,'[]'::jsonb,'["Proper Eating:", "The teacher demonstrates eating properly: sitting down, using utensils correctly, chewing with mouth closed, not talking with mouth full", "The teacher emphasizes washing hands before eating", "The teacher teaches eating slowly and not rushing", "The teacher discusses eating at appropriate times. Table Manners:", "The teacher teaches basic table manners: saying \"Please\" and \"Thank you,\" waiting turn to be served, not grabbing food, using napkin", "The teacher demonstrates proper use of spoon/fork", "The teacher teaches not playing with food", "The teacher emphasizes staying seated while eating. Food Appreciation:", "The teacher teaches not wasting food - eat what is served", "The teacher discusses being grateful for food", "The teacher introduces healthy eating simply (fruits, vegetables)", "The teacher prepares pupils for mid-term assessment"]'::jsonb,'["Proper Eating:", "Pupils learn to sit properly while eating", "Pupils practice using utensils correctly", "Pupils learn to chew with mouth closed", "Pupils understand importance of handwashing before meals. Table Manners:", "Pupils practice saying \"Please\" and \"Thank you\" at meals", "Pupils wait their turn to be served", "Pupils use spoons/forks properly", "Pupils learn not to play with food", "Pupils stay seated while eating. Appreciation:", "Pupils learn not to waste food", "Pupils feel grateful for food", "Pupils learn about healthy foods", "Pupils prepare for mid-term test"]'::jsonb,'["Plates, spoons, forks", "Napkins", "Table setting materials", "Pictures of good eating habits", "Healthy food pictures", "Table manners chart", "Role-play materials"]'::jsonb,280) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t2-w5','ng-scheme-2025-preprimary-primary','N1','social-habits',2,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','[]'::jsonb,'[]'::jsonb,'["Assessment Activities:", "The teacher administers mid-term social habits assessment", "The teacher tests personal hygiene knowledge: when to wash hands, importance of bathing", "The teacher assesses cleanliness and tidiness: proper waste disposal, tidying toys", "The teacher tests sharing and caring: pupils demonstrate sharing, show kindness", "The teacher assesses eating habits: table manners, proper eating behavior", "The teacher evaluates practical application of good habits", "The teacher uses observation, oral questions, and practical demonstrations", "The teacher records pupils'' behavior and social development"]'::jsonb,'["Assessment Tasks:", "Pupils explain when to wash hands and demonstrate proper handwashing", "Pupils demonstrate proper waste disposal and tidying up", "Pupils show sharing toys and books with classmates", "Pupils demonstrate caring behavior", "Pupils show proper eating habits and table manners", "Pupils apply all good habits learned", "Pupils participate in practical demonstrations", "Pupils show social development and good habits"]'::jsonb,'["Assessment materials", "Handwashing station", "Toys and books", "Eating materials", "Waste bins", "Observation checklist", "Mark book"]'::jsonb,281) on conflict (id) do nothing;
