insert into curriculum_topics values ('N1-social-habits-t2-w7','ng-scheme-2025-preprimary-primary','N1','social-habits',2,'7',7,'teaching',null,'Safety at Home and School','["Basic safety rules", "Staying safe at home", "Staying safe at school", "Stranger danger (simple)"]'::jsonb,'[]'::jsonb,'["Safety Introduction:", "The teacher explains safety means keeping ourselves free from danger and harm", "The teacher discusses why safety is important", "The teacher introduces basic safety rules. Home Safety:", "The teacher teaches home safety rules: don''t play with fire/matches, don''t touch electrical outlets, don''t play with knives/sharp objects, don''t open door to strangers, stay away from hot stoves, don''t climb dangerous places", "The teacher shows pictures of safe and unsafe behaviors", "The teacher emphasizes telling adults about dangers. School Safety:", "The teacher teaches school safety: walk, don''t run in classroom, be careful on playground, line up properly, stay with teacher during trips, tell teacher if hurt", "The teacher demonstrates safe behavior in class and playground", "The teacher practices safety rules. Stranger Awareness:", "The teacher introduces stranger danger simply: don''t go with people you don''t know, don''t take things from strangers, don''t talk to strangers when alone, stay close to trusted adults", "The teacher identifies trusted adults: parents, teachers, known family friends", "The teacher role-plays safe responses to strangers"]'::jsonb,'["Safety Understanding:", "Pupils understand safety keeps us from harm", "Pupils learn importance of being safe", "Pupils learn basic safety rules. Home Safety:", "Pupils learn not to play with fire, electricity, sharp objects", "Pupils learn not to open doors to strangers", "Pupils observe safe and unsafe pictures", "Pupils understand to tell adults about dangers. School Safety:", "Pupils learn to walk carefully in school", "Pupils practice safe playground behavior", "Pupils stay with teachers during activities", "Pupils tell teacher when hurt. Stranger Safety:", "Pupils learn not to go with strangers", "Pupils understand not to take things from strangers", "Pupils identify trusted adults", "Pupils practice safe responses in role-plays"]'::jsonb,'["Safety pictures", "Safe/unsafe behavior charts", "Role-play props", "Safety rules posters", "Pictures of trusted adults", "Story books about safety"]'::jsonb,282) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t2-w8','ng-scheme-2025-preprimary-primary','N1','social-habits',2,'8',8,'teaching',null,'Respecting Others','["Showing respect to elders", "Respecting teachers", "Respecting classmates", "Respect for property"]'::jsonb,'[]'::jsonb,'["Respect Introduction:", "The teacher explains respect means treating others well and showing we value them", "The teacher demonstrates respectful behavior", "The teacher discusses why respect is important. Respecting Elders:", "The teacher teaches respect for parents, grandparents, older relatives: listen to them, obey them, greet them properly, help them, speak politely", "The teacher demonstrates respectful body language (no shouting, no talking back)", "The teacher emphasizes elders deserve special respect. Respecting Teachers:", "The teacher discusses respecting teachers: listen when teacher talks, follow instructions, greet teacher, raise hand to speak, don''t disturb class", "The teacher practices classroom respect rules. Respecting Peers and Property:", "The teacher teaches respecting classmates: be kind, don''t hit or push, don''t take others'' things, listen when they speak, play nicely", "The teacher teaches respecting property: don''t break toys, handle books carefully, take care of school materials", "The teacher rewards respectful behavior"]'::jsonb,'["Understanding Respect:", "Pupils understand respect means treating others well", "Pupils observe respectful behavior", "Pupils learn why respect is important. Respecting Elders:", "Pupils learn to respect parents, grandparents, older relatives", "Pupils practice listening and obeying elders", "Pupils speak politely to elders", "Pupils understand elders deserve special respect. Respecting Teachers:", "Pupils show respect to teachers", "Pupils listen when teacher talks", "Pupils follow teacher''s instructions", "Pupils maintain classroom respect. Respecting Peers:", "Pupils treat classmates kindly", "Pupils handle toys and books carefully", "Pupils take care of school materials", "Pupils enjoy being respectful"]'::jsonb,'["Respect charts", "Pictures of respectful behavior", "Role-play materials", "Classroom rules poster", "Reward stickers", "Story books about respect"]'::jsonb,283) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t2-w9','ng-scheme-2025-preprimary-primary','N1','social-habits',2,'9',9,'teaching',null,'Feelings and Emotions','["Identifying feelings", "Happy, sad, angry, afraid", "Expressing feelings appropriately", "Understanding others'' feelings"]'::jsonb,'[]'::jsonb,'["Identifying Feelings:", "The teacher introduces basic feelings: happy, sad, angry, afraid, surprised, excited", "The teacher shows pictures of facial expressions for each feeling", "The teacher demonstrates each feeling with facial expressions and body language", "The teacher helps pupils name feelings they experience. Expressing Feelings:", "The teacher teaches it''s okay to have feelings", "The teacher demonstrates appropriate ways to express feelings: saying \"I feel sad\" instead of crying uncontrollably, saying \"I feel angry\" instead of hitting", "The teacher teaches asking for help when feeling overwhelmed", "The teacher practices using \"feeling words\" Understanding Others:", "The teacher teaches recognizing feelings in others by looking at faces and listening to voices", "The teacher demonstrates empathy: if someone is sad, ask \"Are you okay?\" or try to help", "The teacher discusses not hurting others'' feelings", "The teacher reads stories about feelings", "The teacher plays feelings identification games"]'::jsonb,'["Identifying Feelings:", "Pupils learn about basic feelings", "Pupils observe facial expressions for each feeling", "Pupils watch teacher demonstrate feelings", "Pupils name feelings they have experienced. Expressing Feelings:", "Pupils understand all feelings are okay", "Pupils learn to express feelings appropriately", "Pupils practice saying \"I feel...\"", "Pupils learn to ask for help with big feelings. Understanding Others:", "Pupils recognize feelings in classmates", "Pupils show empathy when others are sad or hurt", "Pupils try not to hurt others'' feelings", "Pupils listen to feelings stories", "Pupils play feelings games"]'::jsonb,'["Feelings flashcards", "Emotion face pictures", "Feelings chart", "Mirror", "Story books about emotions", "Feelings games", "Role-play props"]'::jsonb,285) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t2-w10','ng-scheme-2025-preprimary-primary','N1','social-habits',2,'10',10,'teaching',null,'Listening and Following Instructions','["Importance of listening", "Listening to parents and teachers", "Following instructions", "Obeying rules"]'::jsonb,'[]'::jsonb,'["Importance of Listening:", "The teacher explains listening means paying attention when someone talks", "The teacher demonstrates good listening: looking at speaker, being quiet, thinking about what is said", "The teacher discusses why listening is important: to learn, stay safe, understand, be respectful. Listening Practice:", "The teacher teaches listening to parents at home and teachers at school", "The teacher demonstrates active listening behaviors", "The teacher plays listening games (Simon Says, following verbal instructions)", "The teacher rewards good listening. Following Instructions:", "The teacher explains instructions are directions we should follow", "The teacher demonstrates following simple instructions: \"Please sit down,\" \"Line up,\" \"Put books away\"", "The teacher practices one-step and two-step instructions", "The teacher emphasizes doing what we''re told promptly. Obedience:", "The teacher teaches obeying rules at home and school keeps us safe and helps everything run smoothly", "The teacher reviews classroom rules", "The teacher prepares pupils for revision week"]'::jsonb,'["Understanding Listening:", "Pupils understand what listening means", "Pupils learn good listening behaviors", "Pupils understand why listening is important. Practice:", "Pupils listen carefully to parents and teachers", "Pupils practice active listening", "Pupils play listening games", "Pupils enjoy listening activities. Following Instructions:", "Pupils understand instructions are directions", "Pupils follow simple instructions given by teacher", "Pupils practice one-step and two-step tasks", "Pupils do what they''re told promptly. Obedience:", "Pupils understand importance of obeying rules", "Pupils follow classroom rules", "Pupils prepare for revision"]'::jsonb,'["Listening games materials", "Instruction cards", "Simon Says props", "Classroom rules chart", "Reward stickers", "Pictures of listening"]'::jsonb,286) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t2-w11','ng-scheme-2025-preprimary-primary','N1','social-habits',2,'11',11,'revision',null,'REVISION OF SECOND TERM WORK All social habits topics','[]'::jsonb,'[]'::jsonb,'["Comprehensive Revision:", "The teacher systematically reviews personal hygiene: handwashing, bathing, cleanliness", "The teacher revises cleanliness and tidiness: waste disposal, organizing toys/books", "The teacher reviews sharing and caring: sharing toys, being kind", "The teacher revises good eating habits: table manners, not wasting food", "The teacher reviews safety rules: home safety, school safety, stranger danger", "The teacher revises respect: for elders, teachers, classmates, property", "The teacher reviews feelings and emotions: identifying, expressing appropriately", "The teacher revises listening and following instructions", "The teacher uses games, role-plays, demonstrations for revision", "The teacher conducts mock examination", "The teacher reinforces all good social habits", "The teacher builds confidence for final examination"]'::jsonb,'["Revision Activities:", "Pupils demonstrate proper handwashing and cleanliness practices", "Pupils show proper waste disposal and tidying", "Pupils demonstrate sharing and caring behaviors", "Pupils show good eating habits and table manners", "Pupils recall and practice safety rules", "Pupils demonstrate respectful behavior to all", "Pupils identify and appropriately express feelings", "Pupils demonstrate good listening and following instructions", "Pupils participate in all revision activities enthusiastically", "Pupils complete mock examination", "Pupils show mastery of good social habits", "Pupils demonstrate readiness for examination"]'::jsonb,'["All term''s materials", "Handwashing station", "Safety pictures", "Feelings cards", "Respect charts", "Eating materials", "Sharing toys", "Revision worksheets", "Mock test materials", "Games and role-play props"]'::jsonb,288) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t2-w12','ng-scheme-2025-preprimary-primary','N1','social-habits',2,'12',12,'examination',null,'End of Term Examination','[]'::jsonb,'[]'::jsonb,'["Examination Administration:", "The teacher administers comprehensive end-of-term examination", "The teacher tests personal hygiene: handwashing demonstration, cleanliness knowledge", "The teacher assesses cleanliness and tidiness through observation and practical tasks", "The teacher tests sharing and caring: pupils demonstrate sharing and kindness", "The teacher assesses eating habits: table manners demonstration", "The teacher tests safety knowledge: pupils explain safety rules for home and school", "The teacher assesses respect: pupils demonstrate respectful behavior", "The teacher tests feelings identification and expression", "The teacher evaluates listening skills and following instructions", "The teacher uses oral questions, practical demonstrations, observation, and role-plays", "The teacher marks and prepares comprehensive report cards"]'::jsonb,'["Examination Tasks:", "Pupils demonstrate proper handwashing technique", "Pupils show cleanliness and tidying skills", "Pupils demonstrate sharing toys and caring for others", "Pupils show proper table manners during snack time", "Pupils explain safety rules and identify safe/unsafe behaviors", "Pupils demonstrate respectful behavior to teacher and classmates", "Pupils identify feelings in pictures and express their own appropriately", "Pupils show good listening skills and follow multi-step instructions", "Pupils participate in all examination activities", "Pupils demonstrate complete understanding of second term social habits"]'::jsonb,'["Examination materials", "Handwashing station", "Eating materials", "Toys for sharing", "Safety pictures", "Feelings cards", "Respect scenarios", "Observation checklist", "Mark book", "Report cards"]'::jsonb,289) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t2-w13','ng-scheme-2025-preprimary-primary','N1','social-habits',2,'13',13,'closing',null,'Closing & End of Term Activities','[]'::jsonb,'[]'::jsonb,'["Closing Activities:", "The teacher returns marked work with positive feedback and encouragement", "The teacher discusses individual social and behavioral development", "The teacher celebrates pupils'' progress in good habits", "The teacher awards certificates for exemplary social behavior", "The teacher distributes report cards with detailed behavior comments", "The teacher provides holiday reminders: practice hygiene, be safe, share, respect family, listen to parents", "The teacher gives preview of third term topics", "The teacher encourages continued practice of good social habits during holidays"]'::jsonb,'["Closing Activities:", "Pupils receive marked work and report cards", "Pupils listen to feedback about their social development", "Pupils celebrate their good habits and achievements", "Pupils receive behavior certificates and awards", "Pupils get holiday social habits reminders", "Pupils look forward to third term", "Pupils say polite goodbyes using all courtesy learned", "Pupils leave with pride in their social development"]'::jsonb,'["Report cards", "Marked work", "Behavior certificates", "Achievement awards", "Holiday reminders sheet", "Celebration materials", "Parent feedback forms"]'::jsonb,290) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w1','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'1',1,'teaching',null,'Our Environment','["Understanding our environment", "Things in our environment", "Taking care of our environment"]'::jsonb,'[]'::jsonb,'["Introduction to Environment:", "The teacher welcomes pupils back and briefly reviews second term", "The teacher explains environment means everything around us: home, school, neighborhood, nature", "The teacher discusses things in our environment: people, animals, plants, buildings, roads, air, water", "The teacher takes pupils on environment observation walk. Types of Environment:", "The teacher discusses different environments: home environment, school environment, neighborhood, natural environment (parks, forests)", "The teacher shows pictures of various environments", "The teacher compares clean and dirty environments. Caring for Environment:", "The teacher teaches we must take care of our environment", "The teacher demonstrates: don''t litter, use waste bins, plant trees, don''t destroy plants, keep surroundings clean", "The teacher organizes environmental clean-up activity", "The teacher emphasizes beautiful environments make us happy and healthy"]'::jsonb,'["Learning Environment:", "Pupils understand environment is everything around us", "Pupils identify things in environment: people, animals, plants, buildings", "Pupils go on observation walk. Types:", "Pupils learn about different environments", "Pupils observe environment pictures", "Pupils compare clean and dirty environments. Care:", "Pupils understand importance of caring for environment", "Pupils learn not to litter and to keep environment clean", "Pupils participate in clean-up activity", "Pupils appreciate beautiful, clean environments"]'::jsonb,'["Environment pictures", "Clean/dirty environment comparison", "Waste collection bags", "Gloves for clean-up", "Plants", "Environment charts", "Nature walk area"]'::jsonb,292) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w2','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'2',2,'teaching',null,'Our Environment (Continued)','["Living and non-living things in environment", "Animals in our environment", "Plants in our environment", "Protecting nature"]'::jsonb,'[]'::jsonb,'["Living and Non- Living:", "The teacher reviews living things (from pre-science): people, animals, plants - they grow, move, eat, breathe", "The teacher introduces non-living things: rocks, water, air, buildings, toys - they don''t grow or move on their own", "The teacher helps pupils sort pictures into living and non-living. Animals and Plants:", "The teacher discusses animals in our environment: pets, birds, insects, farm animals", "The teacher discusses plants around us: trees, flowers, grass, vegetables", "The teacher emphasizes both are important for our world. Protecting Nature:", "The teacher teaches being kind to animals: don''t hurt them, feed pets, don''t destroy nests", "The teacher teaches protecting plants: don''t uproot, water plants, don''t break branches", "The teacher discusses how plants and animals help us", "The teacher conducts nature appreciation activities"]'::jsonb,'["Living and Non-Living:", "Pupils recall living things from pre-science", "Pupils learn about non-living things", "Pupils sort pictures into living and non-living categories. Animals and Plants:", "Pupils identify animals in environment", "Pupils identify plants around them", "Pupils understand importance of animals and plants. Protection:", "Pupils learn to be kind to animals", "Pupils learn to protect plants", "Pupils understand how plants and animals help us", "Pupils appreciate nature"]'::jsonb,'["Pictures of living and non-living things", "Sorting cards", "Pictures of animals and plants", "Nature protection posters", "Real plants", "Story books about nature"]'::jsonb,293) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w3','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'3',3,'teaching',null,'Good Manners','["Review and reinforcement of courtesy", "Polite behavior in public", "Excuse me, May I, Please", "Being well-behaved"]'::jsonb,'[]'::jsonb,'["Review of Courtesy:", "The teacher reviews all courtesy learned: greetings, \"Thank you,\" \"I am sorry\"", "The teacher emphasizes consistent use of polite words", "The teacher rewards pupils using courtesy naturally. Additional Polite Phrases:", "The teacher introduces \"Excuse me\": when passing by someone, when interrupting (politely), when you need attention, after burping/sneezing", "The teacher introduces \"May I...?\" for asking permission: \"May I go to the toilet?\", \"May I have water?\", \"May I play with this?\"", "The teacher reinforces \"Please\" when asking for anything", "The teacher practices all polite phrases through role-plays. Public Behavior:", "The teacher discusses behaving well in public places: markets, church/mosque, parties, restaurants", "The teacher teaches: speak quietly, don''t run around, stay close to adults, be respectful, don''t touch things that aren''t yours", "The teacher emphasizes good manners everywhere, not just at school", "The teacher role-plays various public scenarios"]'::jsonb,'["Review:", "Pupils review all courtesy phrases learned", "Pupils use polite words consistently", "Pupils enjoy being courteous. New Phrases:", "Pupils learn \"Excuse me\" and when to use it", "Pupils learn \"May I...?\" for asking permission", "Pupils practice saying \"Please\" when requesting", "Pupils participate in courtesy role-plays. Public Behavior:", "Pupils learn how to behave in public places", "Pupils understand public behavior rules", "Pupils know good manners apply everywhere", "Pupils participate in public scenario role-plays"]'::jsonb,'["Courtesy charts", "Role-play props", "Public places pictures", "Polite phrases flashcards", "Reward stickers", "Story books about manners"]'::jsonb,294) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w4','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'4',4,'teaching',null,'Gender Fairness','["Boys and girls are equal", "Everyone can do things", "No gender stereotypes", "Respecting everyone"]'::jsonb,'[]'::jsonb,'["Gender Equality Introduction:", "The teacher explains boys and girls are equally important and valuable", "The teacher discusses we are different but equal", "The teacher emphasizes everyone deserves respect regardless of being boy or girl. Breaking Stereotypes:", "The teacher teaches both boys and girls can: play with any toys, do any activities, be good at different things, have any dreams", "The teacher shows pictures of men and women in various professions", "The teacher discusses: girls can play with cars, boys can play with dolls; girls can be doctors, boys can be nurses; anyone can cook, clean, or build", "The teacher emphasizes no job or activity is \"only for boys\" or \"only for girls\" Respect and Inclusion:", "The teacher teaches treating everyone kindly regardless of gender", "The teacher encourages boys and girls to play together", "The teacher addresses any gender-based teasing firmly", "The teacher celebrates diversity and equality", "The teacher prepares pupils for mid-term assessment"]'::jsonb,'["Understanding Equality:", "Pupils understand boys and girls are equally important", "Pupils learn we are different but equal", "Pupils respect everyone regardless of gender. No Stereotypes:", "Pupils understand both boys and girls can do anything", "Pupils see men and women in various jobs", "Pupils learn anyone can play with any toys", "Pupils understand no limits based on gender. Respect:", "Pupils treat everyone kindly", "Pupils play with both boys and girls", "Pupils don''t tease based on gender", "Pupils celebrate equality", "Pupils prepare for mid-term test"]'::jsonb,'["Pictures of men and women in various professions", "Diverse toy collection", "Equality posters", "Story books about gender equality", "Flashcards", "Activity materials"]'::jsonb,296) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w5','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'5',5,'midterm_assessment',null,'Mid-term Assessment/tes T','[]'::jsonb,'[]'::jsonb,'["Assessment Activities:", "The teacher administers mid-term social habits assessment", "The teacher tests environment knowledge: identifying things in environment, living vs non-living", "The teacher assesses environmental care: pupils explain how to care for environment", "The teacher tests good manners: pupils demonstrate all courtesy phrases including \"Excuse me\" and \"May I\"", "The teacher assesses gender fairness understanding: pupils explain boys and girls are equal", "The teacher evaluates respectful, inclusive behavior", "The teacher uses oral questions, picture identification, and practical demonstrations", "The teacher records pupils'' understanding and behavior"]'::jsonb,'["Assessment Tasks:", "Pupils identify things in environment", "Pupils sort living and non-living things", "Pupils explain how to care for environment", "Pupils demonstrate all courtesy phrases learned", "Pupils show polite behavior in role-play scenarios", "Pupils explain that boys and girls are equal and can do anything", "Pupils demonstrate respectful, inclusive behavior", "Pupils show understanding of third term topics"]'::jsonb,'["Assessment materials", "Environment pictures", "Living/non-living sorting cards", "Courtesy scenario cards", "Gender equality pictures", "Observation checklist", "Mark book"]'::jsonb,297) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w6','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,298) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w7','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'7',7,'teaching',null,'Helping Others','["Importance of helping", "Helping at home", "Helping at school", "Community helpers"]'::jsonb,'[]'::jsonb,'["Importance of Helping:", "The teacher explains helping means making things easier for others", "The teacher discusses why helping is important: shows love, builds friendships, makes work easier, makes helpers happy", "The teacher demonstrates various helping actions", "The teacher reads stories about helping. Helping at Home:", "The teacher discusses ways to help at home: putting toys away, helping set table, tidying room, helping younger siblings, doing small chores", "The teacher emphasizes children can be helpers too", "The teacher asks pupils to share how they help at home. Helping at School:", "The teacher discusses ways to help at school: helping classmates who struggle, sharing materials, cleaning up, following instructions, being kind", "The teacher assigns classroom helper roles", "The teacher rewards helpful behavior. Community Helpers:", "The teacher introduces community helpers: teachers, doctors, nurses, police, firefighters, cleaners, drivers", "The teacher discusses how they help us", "The teacher shows appreciation for community helpers"]'::jsonb,'["Understanding Helping:", "Pupils understand helping makes things easier for others", "Pupils learn why helping is important", "Pupils observe helping demonstrations", "Pupils listen to helping stories. Home Helping:", "Pupils learn ways to help at home", "Pupils understand they can be helpers", "Pupils share how they help at home. School Helping:", "Pupils learn ways to help at school", "Pupils help classmates and teachers", "Pupils take on classroom helper roles", "Pupils enjoy being helpful. Community Helpers:", "Pupils learn about community helpers", "Pupils understand how helpers serve us", "Pupils appreciate community helpers"]'::jsonb,'["Pictures of helping behaviors", "Story books about helping", "Community helpers pictures", "Helper badges/stickers", "Role-play props", "Charts about helping"]'::jsonb,298) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w8','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'8',8,'teaching',null,'People and Their Professions','["Different jobs people do", "Importance of all jobs", "What I want to be"]'::jsonb,'[]'::jsonb,'["Introduction to Professions:", "The teacher explains professions are jobs people do to earn money and help society", "The teacher shows pictures of people in various professions", "The teacher discusses different workplaces. Various Professions:", "The teacher presents professions: teacher, doctor, nurse, engineer, farmer, driver, chef, pilot, police officer, firefighter, artist, shopkeeper, banker", "The teacher discusses what each profession does", "The teacher shows tools/uniforms associated with each profession", "The teacher emphasizes all jobs are important and deserving of respect. Career Aspirations:", "The teacher asks pupils \"What do you want to be when you grow up?\"", "The teacher encourages diverse career aspirations", "The teacher validates all career choices", "The teacher helps pupils draw themselves in their dream profession", "The teacher discusses that education helps us get good jobs"]'::jsonb,'["Learning Professions:", "Pupils understand professions are jobs people do", "Pupils observe pictures of various professions", "Pupils learn about different workplaces. Various Jobs:", "Pupils learn about many different professions", "Pupils understand what each profession does", "Pupils identify tools and uniforms for professions", "Pupils understand all jobs are important. Career Dreams:", "Pupils think about what they want to be", "Pupils share their career dreams", "Pupils feel their dreams are valued", "Pupils draw themselves in dream careers", "Pupils understand education is important for careers"]'::jsonb,'["Pictures of various professions", "Career flashcards", "Professional tools/uniform pictures", "Drawing materials", "Career dress-up props (optional)", "Story books about professions"]'::jsonb,299) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w9','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'9',9,'teaching',null,'Transportation in My Neighbourhood & Means of Transportation','["Vehicles around us", "Land, water, air transportation", "Road safety basics"]'::jsonb,'[]'::jsonb,'["Neighborhood Transportation:", "The teacher discusses vehicles commonly seen in neighborhood: cars, buses, motorcycles, bicycles, tricycles (keke), trucks", "The teacher asks pupils what vehicles they see daily", "The teacher discusses how people travel in the neighborhood. Means of Transportation:", "The teacher categorizes transportation: Land (cars, buses, trains, bicycles), Water (boats, ships), Air (airplanes, helicopters)", "The teacher shows pictures of each type", "The teacher discusses which is fastest, which carries most people, etc", "The teacher asks pupils about their travel experiences. Basic Road Safety:", "The teacher introduces basic road safety: look left and right before crossing, use pedestrian crossings/zebra crossings, hold adult''s hand when crossing, obey traffic lights (red-stop, green-go), don''t play on the road", "The teacher demonstrates safe road crossing", "The teacher shows traffic light colors and meanings", "The teacher emphasizes safety is most important", "The teacher plays road safety games"]'::jsonb,'["Neighborhood Vehicles:", "Pupils identify vehicles in their neighborhood", "Pupils share vehicles they see daily", "Pupils discuss how people travel around them. Transportation Types:", "Pupils learn about land, water, and air transportation", "Pupils observe pictures of various vehicles", "Pupils compare different transportation types", "Pupils share their travel experiences. Road Safety:", "Pupils learn basic road safety rules", "Pupils understand importance of looking before crossing", "Pupils learn about traffic lights", "Pupils understand not to play on roads", "Pupils play road safety games"]'::jsonb,'["Pictures of various vehicles", "Land/water/ai r transportation charts", "Traffic light model", "Zebra crossing demonstration", "Road safety posters", "Toy vehicles", "Road safety games"]'::jsonb,301) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w10','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'10',10,'teaching',null,'Our Country - Nigeria','["Name of our country", "Nigerian flag", "Being Nigerian", "National pride"]'::jsonb,'[]'::jsonb,'["Introduction to Nigeria:", "The teacher teaches pupils the name of their country: Nigeria", "The teacher helps pupils say \"I am Nigerian\" or \"I am from Nigeria\"", "The teacher shows map of Nigeria (simple introduction)", "The teacher discusses what makes Nigeria special. Nigerian Flag:", "The teacher shows the Nigerian flag: green-white-green", "The teacher explains green represents agriculture/forests, white represents peace", "The teacher helps pupils draw and color Nigerian flag", "The teacher teaches flag respect. Being Nigerian:", "The teacher discusses Nigerian culture simply: foods, languages, festivals, dances", "The teacher shows pictures of Nigerian landmarks, traditional dress, foods", "The teacher teaches simple Nigerian greeting in local language (if appropriate)", "The teacher discusses national symbols: flag, coat of arms (show picture). National Pride:", "The teacher encourages love for Nigeria", "The teacher teaches (simply) that we should be good citizens: obeying rules, being kind, keeping environment clean, respecting others", "The teacher prepares pupils for revision week"]'::jsonb,'["Learning About Nigeria:", "Pupils learn Nigeria is their country", "Pupils practice saying \"I am Nigerian\"", "Pupils observe map of Nigeria", "Pupils learn what makes Nigeria special. Nigerian Flag:", "Pupils identify Nigerian flag colors", "Pupils learn meaning of flag colors", "Pupils draw and color Nigerian flag", "Pupils learn to respect the flag. Nigerian Culture:", "Pupils learn about Nigerian culture", "Pupils observe pictures of Nigerian things", "Pupils learn simple greeting in local language", "Pupils see national symbols. Pride:", "Pupils feel proud to be Nigerian", "Pupils understand being good citizens", "Pupils prepare for revision"]'::jsonb,'["Nigerian flag", "Map of Nigeria", "Pictures of Nigerian culture", "Nigerian foods pictures", "Traditional dress pictures", "National symbols pictures", "Drawing materials", "Green and white paper/crayons"]'::jsonb,302) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w11','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'11',11,'revision',null,'REVISION OF THIRD TERM & YEAR''S WORK All social habits from three terms','[]'::jsonb,'[]'::jsonb,'["Comprehensive Year-End Revision: Third Term Review:", "The teacher reviews environment: caring for environment, living/non-living things", "The teacher revises good manners: all courtesy phrases", "The teacher reviews gender fairness: boys and girls are equal", "The teacher revises helping others and community helpers", "The teacher reviews professions and career aspirations", "The teacher revises transportation and road safety", "The teacher reviews Nigeria: flag, being Nigerian, national pride. First Term Review:", "The teacher briefly reviews: self-awareness, courtesy (greetings, thank you, sorry), family, family roles, school awareness. Second Term Review:", "The teacher briefly reviews: hygiene, cleanliness, sharing, eating habits, safety, respect, feelings, listening. Comprehensive Activities:", "The teacher uses games, songs, role-plays, demonstrations for fun year-end revision", "The teacher conducts comprehensive mock examination covering all three terms", "The teacher celebrates year-long social development journey", "The teacher builds strong confidence for final examination"]'::jsonb,'["Comprehensiv e Revision: Third Term:", "Pupils explain caring for environment", "Pupils demonstrate all courtesy phrases", "Pupils explain gender equality", "Pupils discuss helping others", "Pupils name various professions", "Pupils identify transportation types and practice road safety", "Pupils show knowledge of Nigeria and flag. First Term:", "Pupils recall self-awareness, courtesy, family topics from first term. Second Term:", "Pupils recall hygiene, safety, respect, feelings topics from second term. Activities:", "Pupils participate enthusiastically in all revision activities", "Pupils complete comprehensive mock examination", "Pupils celebrate their amazing year-long social development!", "Pupils demonstrate readiness for final examination"]'::jsonb,'["All year''s materials", "Environment pictures", "Courtesy charts", "Gender equality posters", "Helping pictures", "Profession flashcards", "Transportation pictures", "Nigerian flag", "Comprehensive revision worksheets", "Mock examination", "Celebration materials"]'::jsonb,304) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w12','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'12',12,'examination',null,'End of Year Examination','[]'::jsonb,'[]'::jsonb,'["Final Examination Administration:", "The teacher administers comprehensive end-of-year social habits examination. Third Term Topics:", "The teacher tests environment knowledge, good manners (all courtesy), gender fairness, helping others, professions, transportation, Nigeria. Second Term Topics:", "The teacher tests hygiene, cleanliness, sharing, eating habits, safety, respect, feelings, listening. First Term Topics:", "The teacher tests self-awareness, courtesy (greetings, thank you, sorry), family knowledge, school awareness. Assessment Methods:", "The teacher uses oral questions, role-plays, practical demonstrations, picture identification", "The teacher observes overall social behavior, courtesy, respect, kindness throughout examination", "The teacher assesses year-long social development and character growth", "The teacher marks thoroughly and prepares comprehensive end-of-year report cards with detailed behavior comments"]'::jsonb,'["Final Examination Tasks: Third Term:", "Pupils explain environment care, demonstrate courtesy, explain equality, discuss helping, name professions, identify transportation, show Nigeria knowledge. Second Term:", "Pupils demonstrate hygiene practices, show respect, share appropriately, display good eating habits, explain safety, identify feelings. First Term:", "Pupils state name/age, demonstrate all courtesy, identify family members, state school name. Performance:", "Pupils answer all oral questions", "Pupils participate in role-plays", "Pupils demonstrate year-long social development", "Pupils show excellent courtesy, respect, kindness throughout", "Pupils demonstrate complete Nursery 1 social habits mastery!"]'::jsonb,'["Comprehensive examination materials", "All pictures and charts from year", "Role-play props", "Nigerian flag", "Family pictures", "Courtesy cards", "Safety pictures", "Profession pictures", "Transportation pictures", "Observation checklist", "Mark book", "Report cards"]'::jsonb,305) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t3-w13','ng-scheme-2025-preprimary-primary','N1','social-habits',3,'13',13,'closing',null,'Closing, Promotion & Graduation Activities','[]'::jsonb,'[]'::jsonb,'["Year-End Closing:", "The teacher returns marked examination scripts with detailed, encouraging feedback", "The teacher discusses individual year-long social and character development", "The teacher celebrates remarkable growth in courtesy, respect, kindness, and all social habits!", "The teacher awards certificates and prizes for exemplary social behavior and character", "The teacher distributes comprehensive end-of-year report cards", "The teacher provides holiday reminders: continue all good habits learned, be courteous, help family, stay safe, be respectful", "The teacher prepares pupils for promotion to Nursery", "The teacher conducts social habits showcase/graduation where pupils demonstrate courtesy, respect, and good habits to parents", "The teacher celebrates pupils'' transformation into well-mannered, respectful, kind individuals", "The teacher thanks pupils for wonderful year and encourages continued character development", "The teacher celebrates journey through: self-awareness, courtesy, family, hygiene, safety, respect, feelings, environment, equality, helping, professions, Nigeria!"]'::jsonb,'["Year-End Closing:", "Pupils receive marked work and comprehensive report cards", "Pupils listen to year-long social development review with pride", "Pupils celebrate their amazing character growth!", "Pupils receive certificates and awards for social excellence", "Pupils get holiday social habits reminders", "Pupils prepare excitedly for promotion to Nursery", "Pupils participate in social habits showcase, demonstrating courtesy and good manners to parents", "Pupils say polite, respectful goodbyes using all courtesy learned throughout the year", "Pupils feel proud of becoming well-mannered, kind, respectful individuals", "Pupils look forward to continued growth in Nursery", "Pupils celebrate learning: courtesy, kindness, respect, safety, helping, equality, and being good citizens!"]'::jsonb,'["Report cards", "Marked examination scripts", "Character excellence certificates", "Social behavior awards", "Graduation materials", "Holiday social habits reminders", "Social habits showcase displays", "All year''s learning materials", "Celebration decorations", "Parent feedback forms", "\"I Have Good", "Manners!\" badges"]'::jsonb,307) on conflict (id) do nothing;
