insert into curriculum_topics values ('N2-numeracy-t3-w7','ng-scheme-2025-preprimary-primary','N2','numeracy',3,'7',7,'teaching',null,'Weight (Concept of Weight)','["Introduction to the concept of weight", "Understanding that objects have weight", "Heavy and light: comparing weights of different objects", "Heavier, lighter, same weight (equal)", "Using balance scale (simple demonstration)", "Comparing weights by lifting objects", "Ordering objects by weight (lightest to heaviest)", "Estimating weight: which is heavier - a book or a feather?", "Weight vocabulary: heavy, light, heavier, lighter, heaviest, lightest", "Practical weight comparison activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,344) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-numeracy-t3-w8','ng-scheme-2025-preprimary-primary','N2','numeracy',3,'8',8,'teaching',null,'Weight (Continued)','["Continued weight comparison activities", "Sorting objects by weight (heavy, medium, light)", "Introduction to measuring weight (simple)", "Weighing objects using non-standard units (e.g., blocks)", "Understanding that larger doesn''t always mean heavier", "Weight in real life: weighing fruits, vegetables, toys", "Weight estimation and checking", "Drawing and identifying heavy and light objects", "Weight problem-solving: \"If an apple is heavier than a grape, which is lighter?\""]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,344) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-numeracy-t3-w9','ng-scheme-2025-preprimary-primary','N2','numeracy',3,'9',9,'teaching',null,'Money (Paper and Coin, Naira and Kobo)','["Introduction to money and its uses", "Understanding we use money to buy things", "Nigerian currency: Naira (₦) and Kobo (k)", "Recognizing Nigerian coins: 50k, ₦1, ₦2", "Recognizing Nigerian paper money: ₦5, ₦10, ₦20, ₦50 (denominations children commonly see)", "Identifying coin and note values", "Counting money in ones: ₦1, ₦2, ₦3, ₦4, ₦5", "Understanding 100 kobo = ₦1 (simple introduction)", "Money recognition games"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,345) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-numeracy-t3-w10','ng-scheme-2025-preprimary-primary','N2','numeracy',3,'10',10,'teaching',null,'Money (Simple Transactions)','["Continued money recognition", "Counting money: adding coins and small notes", "Simple shopping role-play", "Buying and selling concept: \"This costs ₦5\"", "Matching items to prices", "Giving correct money for purchases (exact amount)", "Understanding change (very simple): buying ₦3 item with ₦5", "Money word problems: \"An orange costs ₦2. How many can you buy with ₦6?\"", "Saving money concept", "Practical money activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,345) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-numeracy-t3-w11','ng-scheme-2025-preprimary-primary','N2','numeracy',3,'11',11,'revision',null,'Revision of Third Term & Year''s Work','["Third Term Revision:", "Subtraction comprehensive review", "Addition and subtraction mixed practice", "Weight concepts revision", "Heavy and light comparison review", "Money recognition and counting revision", "Simple transactions practice Year-Long Comprehensive Revision:", "Numbers 1-100: counting, recognition, writing", "Number patterns and sequences", "Shapes identification", "Fraction ½", "Ordinal numbers (1st-5th)", "Ascending and descending order", "Place value (tens and ones)", "Addition and subtraction", "Weight comparison", "Money recognition", "Mock examination covering all three terms"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,345) on conflict (id) do nothing;
