insert into curriculum_topics values ('N2-basic-science-and-technology-t1-w1','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',1,'1',1,'teaching',null,'Dangerous Objects','["Simple meaning of dangerous objects", "Understanding that some objects can hurt us", "Examples of dangerous objects: broken bottles, broken plates/potties, razors, needles, pins, sharp sticks, knives, scissors, nails, glass pieces", "Why these objects are dangerous: they can cut, pierce, or injure", "Identifying dangerous objects in pictures and real samples", "Dangers of playing with dangerous objects", "Ways to avoid dangerous objects: don''t touch, tell an adult, stay away", "Safe behavior around dangerous objects", "What to do if you see a dangerous object", "Safety rules at home and school regarding dangerous objects"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,347) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t1-w2','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',1,'2',2,'teaching',null,'Dangerous Liquids','["Simple meaning of dangerous liquids", "Understanding that some liquids can harm us", "Examples of dangerous liquids: hot water, boiling water, kerosene, petrol, methylated spirit, bleach, detergent, insecticide, acid", "Why these liquids are dangerous: can burn, poison, harm skin, cause illness", "Identifying dangerous liquids and their containers", "Dangers of playing with or drinking dangerous liquids", "Safety signs and warnings on containers", "Ways to avoid dangerous liquids: don''t touch, don''t drink, don''t play with, tell an adult", "What to do if you touch or swallow a dangerous liquid", "Keeping dangerous liquids away from children", "Safety rules for liquids at home and school"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,347) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t1-w3','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',1,'3',3,'teaching',null,'Plants: Observing Parts of a Plant','["Introduction to plants in our environment", "Observing plants and trees around the school and neighborhood", "Identification of a plant", "Parts of a plant: root, stem, leaf, flower, fruit, seed", "Functions of each part (simple explanation): * Root: holds plant in soil, takes in water * Stem: holds plant upright, carries water * Leaf: makes food for plant, green in color * Flower: beautiful part, becomes fruit * Fruit: contains seeds * Seed: grows into new plant", "Observing a real plant sample and identifying parts", "Drawing and labeling parts of a plant", "Importance of plants: food, shade, oxygen, beauty", "Caring for plants: watering, not destroying"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,347) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t1-w4','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',1,'4',4,'teaching',null,'Technology: Introduction to Machines','["Simple meaning of technology: things that help make work easier", "Simple meaning of machines: tools and equipment that help us do work", "Understanding that machines make work easier and faster", "Examples of simple machines at home: broom, spoon, knife, scissors, hammer, bottle opener, wheelbarrow", "Examples of simple machines at school: pencil sharpener, stapler, scissors, hole puncher", "Identifying machines in pictures", "Songs and rhymes about machines", "How machines help us in daily activities", "Differences between using machines and doing work without machines", "Introduction to careful use of machines"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,348) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t1-w5','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',1,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Identification of dangerous objects test", "Naming dangerous liquids assessment", "Safety rules evaluation (dangerous objects and liquids)", "Parts of a plant identification test", "Labeling parts of a plant on diagram", "Drawing a plant assessment", "Definition of technology and machines", "Identification of simple machines (home and school)", "Oral questions on all topics covered", "Picture identification test", "Practical observation and safety awareness evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,348) on conflict (id) do nothing;
