insert into curriculum_topics values ('N2-basic-science-and-technology-t1-w7','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',1,'7',7,'teaching',null,'Simple Machines: Uses at Home','["Review of simple machines from week 4", "Detailed study of machines used at home: * Broom: for sweeping * Knife: for cutting (adults only) * Spoon and fork: for eating * Scissors: for cutting paper, cloth * Hammer: for hitting nails * Screwdriver: for tightening screws * Bottle opener: for opening bottles * Can opener: for opening cans * Wheelbarrow: for carrying heavy things", "Demonstrating how each machine is used", "Importance of careful use of machines", "Safety precautions: some machines are for adults only", "Dangers of misusing machines", "Proper storage of machines after use", "Respecting machines and tools"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,349) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t1-w8','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',1,'8',8,'teaching',null,'Sense Organs: Identification','["Introduction to sense organs of the body", "The five sense organs: * Eyes - for seeing * Ears - for hearing * Nose - for smelling * Tongue - for tasting * Skin - for touching/feeling", "Identifying sense organs on a labeled diagram", "Locating sense organs on own body", "Understanding each organ helps us know about our environment", "Touching and pointing to each sense organ", "Songs and rhymes about sense organs and body parts", "Importance of each sense organ", "Taking care of our sense organs", "What happens when a sense organ is not working properly"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,349) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t1-w9','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',1,'9',9,'teaching',null,'Uses of Sense Organs: Functions','["Detailed functions of each sense organ: Eyes (Sense of Sight):", "Seeing objects in the environment", "Identifying colors, shapes, sizes", "Recognizing people and things", "Reading and learning Tongue (Sense of Taste):", "Tasting food: sweet (sugar, candy), bitter (bitter leaf, medicine), sour (lemon, orange), salty (salt)", "Enjoying different flavors Skin (Sense of Touch):", "Feeling textures: soft, hard, rough, smooth", "Feeling temperature: hot, cold, warm", "Feeling pain when hurt Nose (Sense of Smell):", "Smelling pleasant things: flowers, perfume, food, talcum powder", "Smelling unpleasant things: rotten food, dirt, smoke", "Warning us of danger (smoke, gas) Ears (Sense of Hearing):", "Hearing different sounds: loud, quiet, high, low", "Hearing music, voices, warnings", "Listening to teachers and parents", "Practical activities: tasting, touching, smelling, listening, observing", "Importance of all five senses working together"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,349) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t1-w10','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',1,'10',10,'teaching',null,'Drug Abuse','["Simple meaning of drugs: medicine that helps us when sick", "Uses of drugs/medicine: * To cure sickness * To stop pain * To make us feel better when ill * To prevent diseases (vaccines)", "Understanding drugs are given by adults (parents, doctors, nurses)", "Simple meaning of drug abuse: using medicine in wrong way or taking medicine when not sick", "Examples of drug abuse: * Taking medicine without adult permission * Taking too much medicine * Taking someone else''s medicine * Eating sweet-coated medicine like candy", "Dangers of drug abuse: can make you very sick, can harm your body, can cause death", "Rules for medicine safety: * Never take medicine alone * Only take medicine given by parents/adults * Don''t eat medicine like candy * Tell adults if you find medicine * Keep away from medicine cabinets", "Staying safe from medicine and drugs"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,350) on conflict (id) do nothing;
