insert into curriculum_topics values ('N2-basic-science-and-technology-t1-w12','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',1,'12',12,'examination',null,'End of Term Examination','["Dangerous objects identification and safety test", "Dangerous liquids identification and safety test", "Parts of a plant examination (identification, labeling, drawing)", "Functions of plant parts test", "Definition of technology and machines", "Identification of simple machines test (pictures and real objects)", "Uses of machines examination", "Sense organs identification test", "Functions of sense organs comprehensive test", "Matching sense organs to their functions", "Practical test: identifying tastes, textures, smells, sounds", "Drug abuse and medicine safety test", "Overall safety awareness evaluation", "Oral and practical assessments", "Picture identification tests"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,351) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t1-w13','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',1,'13',13,'closing',null,'Closing & End of Term Activities','["Return of marked examination scripts with feedback", "Distribution of report cards", "Celebration of science and technology learning achievements", "Awards for excellent performance in Basic Science", "Review of term''s safety lessons and practical knowledge", "Holiday safety tips and reminders", "Encouragement to observe plants, machines, and practice safety at home", "Fun science games and activities", "Science showcase (if applicable)", "Preview of second term topics", "Farewell activities and holiday wishes"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,351) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t2-w1','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',2,'1',1,'teaching',null,'Water: Definition and Sources','["Simple definition of water: clear liquid we drink and use", "Understanding water is essential for life", "Definition of ''source'': where something comes from", "Sources of water: * Rain (from the sky/clouds) * Tap (in homes and schools) * Well (dug in the ground) * River and stream * Borehole * Spring * Ocean/sea", "Identifying sources of water in pictures and charts", "Understanding rainwater is the primary source of all water", "Sources of water in our community", "Songs and rhymes about water", "Importance of water sources"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,353) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t2-w2','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',2,'2',2,'teaching',null,'Water: Uses and Properties','["Uses of water: * Drinking (most important) * Bathing and washing our bodies * Washing clothes and dishes * Cooking food * Cleaning the house and surroundings * Watering plants * For animals to drink * Swimming and playing", "Properties of clean water: * Colorless (no color, clear) * Odorless (no smell) * Tasteless (no taste, pure) * Can flow and take shape of container", "Difference between clean water and dirty water", "Identifying clean water vs dirty water by observation", "Importance of drinking only clean water", "Water safety: boiling or filtering water", "Not wasting water"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,353) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t2-w3','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',2,'3',3,'teaching',null,'Living and Non-living Things: Meaning and Examples','["Simple definition of living things: things that have life, can grow, move, eat, and breathe", "Simple definition of non-living things: things that do not have life, cannot grow, move by themselves, or eat", "Examples of living things: * People/Humans * Animals (dog, cat, goat, bird, fish, etc.) * Plants (trees, flowers, grass) * Insects (butterfly, ant, bee)", "Examples of non-living things: * Stones and rocks * Tables and chairs * Shoes and clothes * Books and pencils * Cars and bicycles * Water and air", "Identifying living and non-living things in the environment", "Observing living and non-living things around school and home", "Sorting objects into living and non-living categories"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,354) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t2-w4','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',2,'4',4,'teaching',null,'Living and Non-living Things: Differences','["Characteristics of living things: *They move by themselves (walk, run, fly, swim, grow) * They grow (babies grow to adults, seeds grow to plants) *They eat food (animals eat, plants take nutrients from soil) * They breathe (take in air) * They reproduce (have babies/young ones) * They respond to surroundings * They can die", "Characteristics of non-living things: *They do not move by themselves (need to be pushed or carried) * They do not grow * They do not eat or drink * They do not breathe * They do not reproduce * They do not respond * They do not die (but can break or wear out)", "Comparing living and non-living things", "Classification activities: sorting objects", "Songs and rhymes demonstrating characteristics of living things", "Understanding both living and non-living things are important"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,354) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t2-w5','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',2,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Definition of water test", "Sources of water identification", "Uses of water assessment", "Properties of clean water test", "Identifying clean vs dirty water", "Definition of living and non-living things", "Examples of living things test", "Examples of non-living things test", "Characteristics of living things assessment", "Characteristics of non-living things assessment", "Classification test: sorting living and non-living things", "Picture identification tests", "Oral questions on all topics covered"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,355) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t2-w6','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',2,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,355) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t2-w7','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',2,'7',7,'teaching',null,'Animals As Pets','["Definition of pets: tame animals kept at home for friendship and companionship", "Understanding pets are friendly animals we care for", "Examples of animals used as pets: * Dog (puppy) * Cat (kitten) * Rabbit * Fish (in aquarium) * Parrot/bird (in cage) * Tortoise * Guinea pig * Hamster", "Why people keep pets: * Friendship and companionship * Protection (dogs guard homes) * Beauty and entertainment * To teach responsibility", "Ways to care for pets: * Feeding them regularly * Giving them clean water * Providing shelter/home * Bathing and grooming * Taking to veterinary doctor when sick * Playing with them * Showing love and kindness", "Being responsible pet owners", "Understanding pets depend on us for care"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,355) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t2-w8','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',2,'8',8,'teaching',null,'Animals: Domestic and Wild Animals','["Definition of domestic animals: friendly animals that live around or with humans, found at home or farms", "Definition of wild animals: dangerous or harmful animals that live in forests, jungles, or far from humans", "Examples of domestic animals: * Dog, cat, rabbit (pets) * Goat, sheep, cow, pig (farm animals) * Chicken, duck, turkey (poultry) * Horse, donkey (work animals)", "Examples of wild animals: * Lion, tiger, leopard * Elephant, hippopotamus * Snake, crocodile * Bear, wolf * Monkey (some species)", "Differences between domestic and wild animals: * Domestic animals are friendly; wild animals are dangerous *Domestic animals live near humans; wild animals live far away *We can touch domestic animals; we cannot touch wild animals", "Why domestic animals are kept at home: safe, useful, provide food and help", "Why wild animals live away from humans: dangerous, need special environment", "Grouping animals: domestic vs wild", "Respecting all animals"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,356) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t2-w9','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',2,'9',9,'teaching',null,'Insects: Meaning and Examples','["Definition of insects: small living creatures (animals) with six legs", "Understanding insects are everywhere in our environment", "Characteristics of insects: * Very small in size * Have six legs *Have three body parts (head, thorax, abdomen) * Many have wings and can fly * Some crawl on the ground", "Examples of common insects: * Butterfly (beautiful, flies) * Bee (makes honey, flies) * Ant (small, crawls, lives in colonies) * Mosquito (flies, bites, spreads diseases) * Housefly (flies, carries germs) * Cockroach (crawls, found in homes) * Grasshopper (jumps and flies) * Beetle (hard shell, crawls) * Termite (eats wood) * Ladybug/Ladybird (red with spots)", "Observing real insects (safely)", "Identifying insects in pictures and videos", "Understanding insects are living things"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,356) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t2-w10','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',2,'10',10,'teaching',null,'Insects (Continued), Soil, and Sound','["Insects Continued:", "Classification of insects: *Flying insects: butterfly, bee, mosquito, housefly, dragonfly * Crawling insects: ant, cockroach, beetle, termite * Jumping insects: grasshopper, cricket", "Harmful insects: mosquitoes (malaria), houseflies (carry germs), cockroaches (carry germs), termites (destroy wood)", "Helpful insects: bees (make honey, pollinate flowers), butterflies (pollinate flowers), ladybugs (eat harmful insects)", "Safety around insects: some bite or sting", "Keeping environment clean to avoid harmful insects Soil:", "Simple definition of soil: the top layer of earth where plants grow", "Understanding soil is on the ground under our feet", "Observing soil: color (brown, black, red), texture (grainy)", "Feeling and touching soil", "Importance of soil: plants grow in soil, provides food for plants Sound:", "Simple definition of sound: what we hear with our ears", "Understanding sounds are all around us", "Types of sounds: * Loud sounds (shouting, drum, siren, thunder) *Soft/Quiet sounds (whisper, rustling leaves, ticking clock)", "Things that make sound: people talking, animals, music, vehicles, bells", "Making sounds with different objects", "Pleasant vs unpleasant sounds"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,357) on conflict (id) do nothing;
