insert into curriculum_topics values ('N2-basic-science-and-technology-t2-w12','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',2,'12',12,'examination',null,'End of Term Examination','["Water definition and sources test", "Uses and properties of water examination", "Clean vs dirty water identification", "Living and non-living things definition test", "Examples of living and non-living things", "Characteristics/differences test", "Classification assessment (living vs non-living)", "Animals as pets examination", "Care of pets test", "Domestic vs wild animals test", "Examples and grouping of animals", "Insects identification and classification test", "Flying vs crawling insects", "Harmful vs helpful insects", "Soil identification test", "Sound types and sources test", "Picture identification comprehensive test", "Oral and practical assessments", "Overall second term science evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,358) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t2-w13','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',2,'13',13,'closing',null,'Closing & End of Term Activities','["Return of marked examination scripts with feedback", "Distribution of report cards", "Celebration of science learning achievements", "Awards for excellent performance", "Review of term''s practical science knowledge", "Holiday science observation tips: observe water sources, identify living/non-living things, watch animals and insects safely, observe soil, listen to different sounds", "Fun science games and activities", "Science quiz competition (optional)", "Preview of third term topics", "Encouragement for continued curiosity about nature", "Farewell activities and holiday wishes"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,359) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t3-w1','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',3,'1',1,'teaching',null,'Floating Objects in Water','["Understanding what \"floating\" means: staying on top of water, not sinking", "Concept of floating: some objects stay on the surface of water", "Examples of objects that float: * Wood and wooden objects * Plastic bottles (empty) * Cork * Leaves * Paper boats * Sponge * Styrofoam/foam * Balloons (inflated) * Oil * Some fruits (apple, coconut)", "Why objects float: they are light or have air inside", "Practical water experiment: testing objects to see which ones float", "Observing floating objects in a basin/container of water", "Predicting which objects will float before testing", "Understanding boats and ships float on water", "Safety around water"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,360) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t3-w2','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',3,'2',2,'teaching',null,'Sinking Objects in Water','["Understanding what \"sinking\" means: going down to the bottom of water", "Concept of sinking: some objects go down in water", "Examples of objects that sink: * Stones and rocks * Metals (spoon, coin, key, nail) * Glass marble * Scissors * Pencil * Cup (when filled with water) * Sand * Most fruits (orange, mango when ripe)", "Why objects sink: they are heavy or dense", "Practical water experiment: testing objects to see which ones sink", "Comparing floating and sinking objects", "Understanding the difference between light and heavy objects in water", "Sorting objects: will it float or sink?", "Predicting and testing hypothesis", "Fun water play activities with floating and sinking objects"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,360) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t3-w3','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',3,'3',3,'teaching',null,'AIR','["Simple definition of air: invisible substance all around us that we breathe", "Understanding air is everywhere but we cannot see it", "Properties of air: * Invisible (cannot be seen) *Can be felt (when wind blows, when we wave hand) * Has no color * Has no smell (pure air) * Takes up space * Can move", "Ways to feel air: * Wind blowing * Fanning ourselves * Blowing on hands * Inflating balloon", "Demonstrating air occupies space: * Blowing up a balloon * Air in an \"empty\" bottle * Bubbles in water", "Uses of air: * Breathing (most important) * Filling balloons, tires, balls * Drying clothes * Flying kites * Wind turns windmills", "Importance of fresh, clean air", "Simple experiments showing air exists"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,361) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t3-w4','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',3,'4',4,'teaching',null,'Weather: Meaning','["Simple definition of weather: what the sky and air outside are like each day", "Understanding weather is what is happening outside (hot, cold, rainy, sunny, windy, cloudy)", "Weather changes every day", "Weather tells us how to dress and what to do", "Introduction to weather elements: * Sun (brings heat and light) * Rain (water falling from clouds) * Wind (moving air) * Clouds (in the sky) * Temperature (hot or cold)", "Observing today''s weather: What is the weather like today?", "Weather affects our daily activities", "Dressing according to weather", "Understanding weather forecasts (simple introduction)", "Weather songs and rhymes", "Drawing different weather conditions"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,361) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t3-w5','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',3,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Floating objects identification test", "Sinking objects identification test", "Predicting which objects float or sink", "Practical test: sorting objects (float vs sink)", "Air definition and properties test", "Uses of air assessment", "Demonstrating that air exists", "Weather definition test", "Identifying weather elements", "Describing today''s weather", "Picture identification: floating/sinking objects", "Oral questions on all topics covered", "Practical observation tests"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,362) on conflict (id) do nothing;
