insert into curriculum_topics values ('N2-basic-science-and-technology-t3-w7','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',3,'7',7,'teaching',null,'Types of Weather','["Different types of weather conditions: 1. Sunny/Hot Weather: * Sky is clear and bright * Sun is shining * Feels hot * Good for drying clothes, playing outside * Need to wear light clothes, hats, drink water 2. Rainy Weather: * Rain falling from clouds * Sky is usually gray/dark * Can be light rain or heavy rain * Need umbrella, raincoat, boots * Roads and ground become wet * Good for plants to grow 3. Cloudy Weather: * Many clouds in the sky * Sky looks gray * Sun is hidden by clouds * Not very hot * May rain soon 4. Windy Weather: * Strong wind blowing * Trees sway, leaves blow * Clothes on line dry fast * Good for flying kites * Can blow away light objects 5. Cold Weather: * Temperature is low, feels cool or cold * Need to wear warm clothes (sweater, jacket) * Harmattan season (in Nigeria)", "Identifying weather types in pictures", "Appropriate clothing for different weather", "Activities suitable for each weather type", "Weather observation and recording", "Safety in different weather conditions"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,362) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t3-w8','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',3,'8',8,'teaching',null,'Stones','["Simple definition of stones: hard, solid objects found naturally on the ground", "Understanding stones come from rocks", "Characteristics of stones: * Hard and solid * Heavy * Different sizes (small pebbles to large rocks) * Different colors (brown, gray, black, white, red) * Different shapes (round, flat, rough, smooth) * Do not break easily * Non-living things", "Where stones are found: * On the ground * In rivers and streams * On beaches * Mountains * Roads and paths", "Types of stones (simple): * Pebbles (small, smooth stones) * Gravel (tiny stones) * Large rocks * Sand (very tiny stone particles)", "Uses of stones: * Building houses and walls * Making roads * Decoration in gardens * Grinding food (grinding stone) * Children''s play (but must be careful)", "Observing and sorting stones by size, color, shape", "Understanding stones sink in water (from week 2)", "Safety: stones can hurt if thrown; don''t throw stones"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,363) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t3-w9','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',3,'9',9,'teaching',null,'Animals and Their Sounds','["Understanding animals make different sounds to communicate", "Learning sounds different animals make: Domestic Animals: * Dog - barks (bow-wow, woof-woof) * Cat - meows (meow, miaow) * Cow - moos (moo) * Goat - bleats (maa, maa) * Sheep - bleats (baa, baa) * Pig - oinks/grunts (oink, oink) * Horse - neighs (neigh) * Donkey - brays (hee-haw) Poultry/Birds: * Chicken/Hen - clucks (cluck, cluck) * Rooster/Cock - crows (cock-a-doodle-doo) * Duck - quacks (quack, quack) * Turkey - gobbles (gobble, gobble) * Bird - chirps/tweets (tweet, tweet) Wild Animals: * Lion - roars (roar) * Elephant - trumpets * Snake - hisses (ssss) * Frog - croaks (croak, croak) * Bee - buzzes (buzz, buzz)", "Imitating animal sounds", "Matching animals to their sounds", "Animal sound songs and games", "Understanding why animals make sounds (to communicate, warn, call babies)", "Listening to animal sounds (recordings or videos)", "Fun activities: \"What animal am I?\" guessing game by sounds"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,364) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t3-w10','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',3,'10',10,'teaching',null,'Animal Movement','["Animal Movement:", "Understanding animals move in different ways", "Types of animal movements: Walking/Running: *Humans, dogs, cats, goats, cows, horses, elephants Flying: * Birds, butterflies, bees, bats * Use wings to fly in the air Swimming: * Fish, whales, dolphins, ducks * Use fins, flippers, or webbed feet Crawling/Creeping: * Snakes, worms, snails, some insects * Move on their bellies Hopping/Jumping: * Frogs, rabbits, kangaroos, grasshoppers * Use strong back legs Climbing: * Monkeys, squirrels, goats (on rocks) * Use hands, feet, or claws", "Demonstrating different animal movements", "Matching animals to how they move", "Movement games and activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,364) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t3-w11','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',3,'11',11,'teaching',null,'Simple Machines','["Simple Machines", "Review of simple machines from first term", "Simple machines make work easier", "Examples: broom, scissors, spoon, knife, hammer", "Uses of simple machines at home and school", "Safety with machines"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,365) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-basic-science-and-technology-t3-w12','ng-scheme-2025-preprimary-primary','N2','basic-science-and-technology',3,'12',12,'examination',null,'Examination','["Third Term Topics:", "Floating objects identification test", "Sinking objects identification test", "Sorting objects (float vs sink) practical test", "Air properties and uses examination", "Weather types identification test", "Describing different weather conditions", "Stones characteristics and uses test", "Animals and their sounds matching test", "Imitating animal sounds assessment", "Animal movements identification and demonstration", "Simple machines review test"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,365) on conflict (id) do nothing;
