insert into curriculum_topics values ('N2-health-habits-t1-w1','ng-scheme-2025-preprimary-primary','N2','health-habits',1,'1',1,'teaching',null,'Good Grooming','["Meaning of good grooming: keeping our body clean, neat, and well cared for", "Importance of good grooming: looking good, feeling good, staying healthy, making good impression", "Elements of good grooming: clean body, neat hair, clean clothes, trimmed nails, clean teeth, pleasant smell", "Daily grooming habits: bathing, brushing teeth, combing hair, wearing clean clothes", "Understanding good grooming shows self-respect and respect for others", "Looking neat and tidy for school and home"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,366) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t1-w2','ng-scheme-2025-preprimary-primary','N2','health-habits',1,'2',2,'teaching',null,'Care of the Nails','["Understanding what nails are: hard coverings at the tips of fingers and toes", "Importance of clean nails: prevents dirt, germs, and infections", "How to care for nails: keeping them short, clean, and trimmed", "Washing under nails during hand washing", "Why we should not bite nails: spreads germs, looks untidy, damages nails", "Why long nails are not good for children: can scratch, collect dirt, break easily", "Adults should cut children''s nails with nail clippers", "Checking nails daily for cleanliness"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,366) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t1-w3','ng-scheme-2025-preprimary-primary','N2','health-habits',1,'3',3,'teaching',null,'Care of the Hair','["Understanding hair is on our head and needs regular care", "Importance of hair care: prevents lice, dandruff, tangling, keeps hair healthy and neat", "How to care for hair: washing/shampooing regularly (at least twice a week), combing/brushing daily, keeping hair neat", "Using appropriate hair products: shampoo, oil, cream", "Different hair types and styles", "Visiting barber or salon for haircuts", "Not sharing combs, brushes, or hair accessories to prevent lice", "Tying long hair neatly for school"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,366) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t1-w4','ng-scheme-2025-preprimary-primary','N2','health-habits',1,'4',4,'teaching',null,'Care of the Hands','["Understanding hands do many things and need special care", "Importance of hand care: prevents spread of germs and diseases", "When to wash hands: before eating, after using toilet, after playing, after touching dirt, when hands are dirty", "Proper handwashing steps: wet hands, apply soap, scrub all parts (palms, back, between fingers, under nails), rinse, dry", "Keeping hands clean throughout the day", "Not putting dirty hands in mouth or on face", "Using hand sanitizer when water not available", "Protecting hands from injuries"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,367) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t1-w5','ng-scheme-2025-preprimary-primary','N2','health-habits',1,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Good grooming knowledge test", "Nail care assessment", "Hair care evaluation", "Hand care and handwashing demonstration", "Importance of cleanliness test", "Practical handwashing assessment", "Identifying clean vs unclean grooming", "Oral questions on topics covered"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,367) on conflict (id) do nothing;
