insert into curriculum_topics values ('N2-health-habits-t1-w7','ng-scheme-2025-preprimary-primary','N2','health-habits',1,'7',7,'teaching',null,'Care of the Legs','["Understanding legs carry us everywhere and need care", "Importance of leg care: prevents injuries, infections, keeps legs healthy and strong", "How to care for legs: washing daily (especially feet), drying properly (between toes), wearing clean socks, wearing proper footwear", "Keeping toenails short and clean", "Applying lotion/cream to prevent dryness and cracking", "Checking for cuts, bruises, or injuries", "Not walking barefoot in dirty places or where there may be sharp objects", "Washing feet before going to bed"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,367) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t1-w8','ng-scheme-2025-preprimary-primary','N2','health-habits',1,'8',8,'teaching',null,'Care of the Skin','["Understanding skin covers our whole body and is the largest organ", "Functions of skin: protects body, helps us feel things, controls body temperature", "Importance of skin care: prevents rashes, infections, keeps skin healthy and glowing", "How to care for skin: daily bathing with soap and water, drying properly, applying lotion/cream (especially after bathing), protecting from sun, wearing clean clothes", "Drinking plenty of water for healthy skin", "Not scratching skin with dirty nails", "Telling adults about rashes, cuts, or skin problems", "Understanding different skin colors are all beautiful"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,367) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t1-w9','ng-scheme-2025-preprimary-primary','N2','health-habits',1,'9',9,'teaching',null,'Care of the Ears','["Understanding ears help us hear sounds", "Parts of ear: outer ear (what we see), ear canal, eardrum (inside)", "Importance of ear care: protects hearing, prevents infections, keeps ears clean", "How to care for ears: washing outer ear gently during bath, drying ears after bath or swimming, not putting anything in ears (fingers, sticks, pencils, cotton buds deep inside)", "Keeping ears clean but letting ear wax do its job (protects ear)", "Adults clean ears safely if needed", "Protecting ears from loud noises", "Telling adults about earache or hearing problems"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,368) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t1-w10','ng-scheme-2025-preprimary-primary','N2','health-habits',1,'10',10,'teaching',null,'Care of the Nose','["Understanding nose helps us breathe and smell", "Importance of nose care: keeps nose clean, prevents infections, ensures good breathing", "How to care for nose: keeping nose clean, blowing nose gently with tissue/handkerchief when needed, not picking nose with fingers", "Proper way to blow nose: one nostril at a time, gently", "Not putting objects in nose", "Breathing through nose (not mouth) when possible", "Disposing of used tissues properly", "Washing hands after touching nose", "Telling adults about blocked nose or nosebleeds"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,368) on conflict (id) do nothing;
