insert into curriculum_topics values ('N2-health-habits-t2-w1','ng-scheme-2025-preprimary-primary','N2','health-habits',2,'1',1,'teaching',null,'Care of the Mouth','["Understanding mouth is for eating, drinking, speaking, and tasting", "Parts of mouth: lips, teeth, tongue, gums", "Importance of mouth care: prevents tooth decay, bad breath, gum disease, keeps teeth healthy", "How to care for mouth: brushing teeth twice daily (morning and night), using toothbrush and toothpaste, rinsing mouth after eating", "Not eating too many sweets and sugary foods", "Visiting dentist regularly", "Not putting dirty objects in mouth", "Keeping lips clean and moist"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,370) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t2-w2','ng-scheme-2025-preprimary-primary','N2','health-habits',2,'2',2,'teaching',null,'Care of the Mouth (Practical)','["Practical tooth brushing demonstration", "Correct toothbrushing technique: up and down, circular motions, brush all surfaces (front, back, top), brush tongue gently, rinse mouth thoroughly", "How much toothpaste to use (pea-sized amount)", "Brushing for at least 2 minutes", "Spitting out toothpaste, not swallowing", "Rinsing toothbrush after use and storing upright", "Not sharing toothbrushes", "Practical session: pupils practice brushing with teacher''s guidance", "Understanding healthy teeth are white and strong"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,370) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t2-w3','ng-scheme-2025-preprimary-primary','N2','health-habits',2,'3',3,'teaching',null,'Care of the Eyes','["Understanding eyes help us see and are very important", "Parts of eye: eyeball, eyelids, eyelashes, eyebrows, tears", "Importance of eye care: protects vision, prevents infections, keeps eyes healthy", "How to care for eyes: keeping clean, not rubbing with dirty hands, washing face daily, getting enough sleep, not looking at bright sun, reading in good light", "Protecting eyes from dust, dirt, and chemicals", "Eating foods good for eyes (carrots, fruits, vegetables)", "Not poking or putting objects in eyes", "Wearing glasses if prescribed by doctor", "Telling adults about eye pain or vision problems"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,370) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t2-w4','ng-scheme-2025-preprimary-primary','N2','health-habits',2,'4',4,'teaching',null,'Personal Hygiene','["Meaning of personal hygiene: keeping our whole body clean and healthy", "Importance of personal hygiene: prevents diseases, makes us look and feel good, shows self-respect", "Complete personal hygiene routine: daily bathing, brushing teeth, washing hands, clean clothes, neat hair, trimmed nails, clean shoes", "Understanding germs are everywhere and hygiene prevents illness", "Hygiene at home, school, and play", "Not sharing personal items: toothbrush, towel, comb, handkerchief", "Covering mouth when coughing or sneezing", "Using toilet properly and flushing", "Overall cleanliness as a habit"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,371) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t2-w5','ng-scheme-2025-preprimary-primary','N2','health-habits',2,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Mouth care knowledge test", "Practical tooth brushing assessment", "Eye care evaluation", "Personal hygiene comprehensive test", "Identifying good hygiene practices", "Demonstrating proper hygiene techniques", "Oral questions on topics covered"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,371) on conflict (id) do nothing;
