insert into curriculum_topics values ('N2-health-habits-t2-w7','ng-scheme-2025-preprimary-primary','N2','health-habits',2,'7',7,'teaching',null,'Cleanliness: Dressing','["Importance of wearing clean clothes: prevents skin infections, makes us look neat, shows self-respect", "Daily clothing hygiene: wearing fresh, clean clothes daily, changing clothes after bath, wearing appropriate clothes for different activities", "Taking off dirty clothes and putting in laundry basket", "Not wearing clothes that are torn, stained, or smelly", "Folding or hanging clothes properly", "Wearing school uniform neatly and proudly", "Matching clothes appropriately", "Keeping clothes clean during the day (not sitting on dirty surfaces, protecting from spills)", "Understanding clothes protect and cover our bodies"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,371) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t2-w8','ng-scheme-2025-preprimary-primary','N2','health-habits',2,'8',8,'teaching',null,'Cleanliness: Footwear','["Importance of clean footwear: prevents foot infections, looks neat, protects feet", "Types of footwear: shoes, sandals, slippers, boots", "Wearing appropriate footwear: school shoes for school, play shoes for playing, slippers at home", "Daily footwear care: cleaning/wiping shoes, checking for damage, wearing clean socks with closed shoes", "Not sharing footwear (prevents fungal infections)", "Wearing correct shoe size (not too big or too small)", "Taking off shoes when entering home (depending on family rules)", "Storing shoes properly", "Not walking barefoot in dirty or dangerous places"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,371) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t2-w9','ng-scheme-2025-preprimary-primary','N2','health-habits',2,'9',9,'teaching',null,'Personal Safety Rules','["Understanding safety means protecting ourselves from danger and harm", "Safety rules at home: not playing with fire/matches, not touching electrical outlets, not playing with sharp objects, staying away from dangerous liquids and chemicals", "Safety rules at school: walking (not running) in corridors, following teacher''s instructions, playing safely, telling teacher if hurt", "Road safety: holding adult''s hand when crossing, looking left and right, using pedestrian crossings, obeying traffic lights", "Stranger danger: not going with strangers, not accepting things from strangers, staying close to trusted adults, screaming and running if in danger", "Knowing full name, parents'' names, and home address", "Knowing emergency contacts"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,372) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t2-w10','ng-scheme-2025-preprimary-primary','N2','health-habits',2,'10',10,'teaching',null,'First Aid (Basic)','["Simple meaning of first aid: immediate help given when someone is hurt or sick", "Understanding adults give first aid, but children should know basics", "Common minor injuries: cuts, scrapes, bruises, burns, insect bites, nosebleeds", "What to do when injured: stay calm, call for adult help immediately, don''t touch wound with dirty hands", "Basic first aid awareness: clean water for washing wounds, bandages for cuts, cold water for small burns, pressure for nosebleeds", "Importance of first aid kit at home and school", "Never trying to treat serious injuries alone", "Comforting someone who is hurt", "Emergency numbers and when to call adults"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,372) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t2-w11','ng-scheme-2025-preprimary-primary','N2','health-habits',2,'11',11,'revision',null,'Revision of Second Term Work','["Mouth and teeth care review (theory and practical)", "Eye care revision", "Personal hygiene comprehensive review", "Cleanliness in dressing and footwear revision", "Personal safety rules review", "First aid basics revision", "Practical demonstrations review", "Mock examination exercises"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,373) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t2-w12','ng-scheme-2025-preprimary-primary','N2','health-habits',2,'12',12,'examination',null,'End of Term Examination','["Mouth care comprehensive test", "Practical tooth brushing examination", "Eye care assessment", "Personal hygiene test", "Cleanliness (dressing and footwear) evaluation", "Personal safety rules test", "First aid basic knowledge assessment", "Practical demonstrations", "Overall health habits evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,373) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t2-w13','ng-scheme-2025-preprimary-primary','N2','health-habits',2,'13',13,'closing',null,'Closing & End of Term Activities','["Return of marked scripts", "Distribution of report cards", "Celebration of health achievements", "Awards for best health practices", "Holiday health and safety tips", "Encouragement to practice hygiene and safety at home", "Preview of third term topics"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,373) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t3-w1','ng-scheme-2025-preprimary-primary','N2','health-habits',3,'1',1,'teaching',null,'Care of Our Belongings','["Understanding belongings are things that belong to us: school bag, books, pencils, lunch box, toys, clothes", "Importance of caring for belongings: makes them last longer, saves money, shows responsibility, keeps things clean and usable", "How to care for belongings: keeping them clean, putting them in proper places, not throwing or mishandling, repairing when broken, not losing them", "Organizing school bag daily", "Keeping books clean and neat (not tearing, not writing on covers)", "Washing lunch box after use", "Taking care of toys and returning them to proper places", "Respecting others'' belongings too", "Being responsible and organized"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,374) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t3-w2','ng-scheme-2025-preprimary-primary','N2','health-habits',3,'2',2,'teaching',null,'Personal Safety Rules (Expanded)','["Review of safety rules from second term", "Additional home safety: not playing in kitchen when adults are cooking, not climbing on furniture, not playing near staircases, being careful in bathroom (slippery floors)", "School safety: staying in designated play areas, using playground equipment properly, not pushing classmates, lining up orderly", "Water safety: not swimming alone, staying in shallow water, listening to adults around water, wearing floatation devices", "Sun safety: wearing hats in hot sun, staying in shade during hottest hours, drinking plenty of water", "Fire safety: knowing escape routes, not hiding if fire, stop-drop-roll if clothes catch fire", "Digital safety (basic): limiting screen time, asking adults before using devices"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,374) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t3-w3','ng-scheme-2025-preprimary-primary','N2','health-habits',3,'3',3,'teaching',null,'First Aid (Expanded)','["Review of first aid basics from second term", "More first aid awareness: recognizing when someone needs help (crying, bleeding, unconscious, difficulty breathing)", "Calling for help: shouting \"Help!\", finding nearest adult, using phone to call emergency numbers (with adult supervision)", "Understanding different types of injuries need different help", "Never giving medicine without adult permission", "Staying calm in emergencies helps everyone", "Being a good helper: getting water, getting adult, comforting person, staying out of way when adults helping", "Understanding prevention is better than treatment", "First aid heroes: doctors, nurses, paramedics", "Having home emergency contacts displayed"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,374) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t3-w4','ng-scheme-2025-preprimary-primary','N2','health-habits',3,'4',4,'teaching',null,'Exercise','["Meaning of exercise: physical activities that make our body move and work", "Importance of exercise: keeps body strong and healthy, makes bones and muscles strong, helps heart and lungs, prevents obesity, makes us happy, helps us sleep well, gives energy", "Types of exercise for children: running, jumping, skipping, dancing, swimming, playing football, riding bicycle, climbing (safely), playing active games", "Exercise at school: PE lessons, sports, playground activities", "Exercise at home: helping with chores, playing outside, dancing to music", "Exercising safely: warming up, wearing proper clothes and shoes, drinking water, stopping if tired or in pain", "Making exercise fun and regular", "Understanding our bodies are made to move"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,375) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t3-w5','ng-scheme-2025-preprimary-primary','N2','health-habits',3,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Care of belongings test", "Personal safety rules comprehensive assessment", "First aid knowledge evaluation", "Exercise importance and types test", "Demonstrating safety awareness", "Identifying safe vs unsafe behaviors", "Oral questions on topics covered"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,375) on conflict (id) do nothing;
