insert into curriculum_topics values ('N2-health-habits-t3-w7','ng-scheme-2025-preprimary-primary','N2','health-habits',3,'7',7,'teaching',null,'Food and Fruits','["Understanding food gives us energy and helps us grow", "Importance of eating healthy food: strong body, healthy growth, fighting sickness, energy for play and learning", "Different food groups (simple): body-building foods (proteins), energy-giving foods (carbohydrates), protective foods (vitamins and minerals)", "Examples of healthy foods: rice, yam, beans, fish, chicken, eggs, milk, vegetables", "Importance of fruits: provide vitamins, minerals, and fiber, keep us healthy", "Common fruits: apple, orange, banana, mango, pineapple, watermelon, pawpaw, grape", "Benefits of specific fruits (simple)", "Eating variety of fruits and foods", "Washing fruits before eating", "Limiting sweets, candies, and soft drinks"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,375) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t3-w8','ng-scheme-2025-preprimary-primary','N2','health-habits',3,'8',8,'teaching',null,'Food: Breakfast','["Understanding breakfast means \"breaking the fast\" - first meal after sleeping", "Importance of breakfast: most important meal, gives energy for morning, helps us concentrate in school, prevents hunger, helps us grow", "Why we should never skip breakfast", "Healthy breakfast options: bread and egg, cereal with milk, oatmeal, yam and egg, beans, fruits, tea/milk", "Unhealthy breakfast: only sweets or sugary foods", "Eating breakfast at home before coming to school", "Taking time to eat breakfast properly (not rushing)", "Including fruits or fruit juice with breakfast", "Understanding good breakfast = good day"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,376) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t3-w9','ng-scheme-2025-preprimary-primary','N2','health-habits',3,'9',9,'teaching',null,'Healthy Eating Habits','["Eating three meals daily: breakfast, lunch, dinner", "Eating healthy snacks: fruits, nuts, yogurt (not just biscuits and sweets)", "Drinking plenty of water daily (6-8 glasses)", "Eating slowly and chewing food properly", "Washing hands before eating", "Sitting properly while eating", "Not talking with mouth full", "Eating variety of foods (not just one type)", "Trying new foods", "Not wasting food", "Eating right portion sizes", "Limiting junk food (chips, candy, soft drinks)", "Understanding balance: sometimes treats are okay, but healthy food should be regular"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,376) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t3-w10','ng-scheme-2025-preprimary-primary','N2','health-habits',3,'10',10,'teaching',null,'Review of All Health Habits','["Comprehensive review of all health habits from the entire year:", "First Term: Good grooming, care of nails, hair, hands, legs, skin, ears, nose", "Second Term: Care of mouth (theory and practical), eyes, personal hygiene, cleanliness (dressing, footwear), personal safety rules, first aid", "Third Term: Care of belongings, safety rules (expanded), first aid (expanded), exercise, food and fruits, breakfast, healthy eating", "Understanding all habits work together for healthy life", "Creating personal daily health routine", "Commitment to practicing all health habits", "Being healthy, safe, and responsible"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,377) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t3-w11','ng-scheme-2025-preprimary-primary','N2','health-habits',3,'11',11,'revision',null,'Revision of Third Term & Year''s Work','["Care of belongings revision", "Personal safety comprehensive review", "First aid knowledge revision", "Exercise importance and types review", "Food, fruits, and breakfast revision", "Healthy eating habits review", "Complete year''s health habits comprehensive revision"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,377) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-health-habits-t3-w12','ng-scheme-2025-preprimary-primary','N2','health-habits',3,'12',12,'examination',null,'End of Year Examination','["Third Term Topics:", "Care of belongings test", "Personal safety rules comprehensive test", "First aid assessment", "Exercise knowledge test", "Food, fruits, and breakfast evaluation", "Healthy eating habits test Comprehensive Year Assessment:", "All grooming and hygiene topics (nails, hair, hands, legs, skin, ears, nose, mouth, eyes)", "Personal hygiene practices", "Cleanliness (dressing and footwear)", "Safety rules (home, school, road, water, sun, fire)", "First aid basics", "Care of belongings", "Exercise and nutrition", "Overall health habits mastery evaluation", "Practical demonstrations", "Overall healthy living knowledge assessment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,377) on conflict (id) do nothing;
