insert into curriculum_topics values ('N2-social-habits-t1-w1','ng-scheme-2025-preprimary-primary','N2','social-habits',1,'1',1,'teaching',null,'My Family','["Understanding what a family is: people who live together and love each other", "Members of the nuclear family: father, mother, brothers, sisters", "Extended family members: grandparents, uncles, aunts, cousins", "Family relationships and how members are related", "Different family sizes and structures", "Love and care in families", "Drawing and talking about own family", "Family songs and activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,378) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t1-w2','ng-scheme-2025-preprimary-primary','N2','social-habits',1,'2',2,'teaching',null,'Roles of Members of the Family','["Father''s roles: provides for family, protects, works, teaches, plays with children", "Mother''s roles: cares for children, cooks, manages home, works, teaches", "Children''s roles: obey parents, help with chores, study well, respect family members", "Grandparents'' roles: give advice, share wisdom, care for grandchildren", "Everyone working together makes family happy", "Appreciating what each family member does", "Simple household chores children can help with"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,378) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t1-w3','ng-scheme-2025-preprimary-primary','N2','social-habits',1,'3',3,'teaching',null,'Activities at Home and in School','["Activities at home: eating meals together, playing, watching TV, sleeping, helping parents, family prayers", "Activities at school: learning, singing, playing with friends, eating snacks, listening to teacher, art and crafts", "Weekend vs weekday activities", "Differences and similarities between home and school", "Importance of both home and school activities", "Balancing play and learning"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,378) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t1-w4','ng-scheme-2025-preprimary-primary','N2','social-habits',1,'4',4,'teaching',null,'Advantages of Living Together As a Family','["Love and care: family members love and support each other", "Protection and safety: family keeps us safe", "Learning: we learn from parents and elders", "Sharing: sharing food, space, things, happiness, and problems", "Help: family helps when we are sick or in trouble", "Fun and happiness: playing, celebrating, and enjoying together", "Sense of belonging: we have people who care about us", "Growing up in a loving environment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,379) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t1-w5','ng-scheme-2025-preprimary-primary','N2','social-habits',1,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Family members identification", "Roles of family members test", "Home and school activities assessment", "Advantages of family living evaluation", "Oral questions on topics covered", "Drawing family assessment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,379) on conflict (id) do nothing;
