insert into curriculum_topics values ('N2-social-habits-t1-w7','ng-scheme-2025-preprimary-primary','N2','social-habits',1,'7',7,'teaching',null,'Places in the House','["Common rooms in the house: living room, bedroom, kitchen, bathroom, toilet, dining room", "Functions of each room", "Other places: compound/yard, garage, store room", "Understanding privacy in certain rooms (bathroom, bedroom)", "Keeping different rooms clean and tidy", "Safety rules for different rooms (especially kitchen and bathroom)", "Respecting family spaces"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,379) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t1-w8','ng-scheme-2025-preprimary-primary','N2','social-habits',1,'8',8,'teaching',null,'Greetings on Special Occasions','["Birthday greetings: \"Happy Birthday,\" singing birthday songs", "Holiday greetings: \"Happy New Year,\" \"Merry Christmas,\" \"Happy Easter,\" \"Happy Sallah\"", "Wedding greetings: \"Congratulations,\" wishing couple happiness", "Success/achievement greetings: \"Congratulations,\" \"Well done\"", "Get well wishes: \"Get well soon\" for sick people", "Condolence (simple): showing care when someone is sad", "Using appropriate greetings for different occasions"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,380) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t1-w9','ng-scheme-2025-preprimary-primary','N2','social-habits',1,'9',9,'teaching',null,'Good Manners','["Review of courtesy words: please, thank you, sorry, excuse me, you''re welcome", "Greetings: good morning, good afternoon, good evening", "Table manners: eating properly, not talking with mouth full, using utensils", "Polite behavior: not interrupting, waiting turn to speak, listening when others talk", "Respect for elders and peers", "Knocking before entering rooms", "Saying goodbye when leaving", "Being kind and considerate to everyone"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,380) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t1-w10','ng-scheme-2025-preprimary-primary','N2','social-habits',1,'10',10,'teaching',null,'Gender Fairness','["Understanding boys and girls are equally important and valuable", "Both boys and girls can do any activity, play with any toys, have any dream", "Everyone deserves equal respect and fair treatment regardless of gender", "No job or activity is \"only for boys\" or \"only for girls\"", "Treating classmates fairly regardless of whether they are boys or girls", "Respecting everyone''s choices and preferences", "Understanding differences don''t mean inequality", "Celebrating diversity and equality"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,380) on conflict (id) do nothing;
