insert into curriculum_topics values ('N2-social-habits-t2-w1','ng-scheme-2025-preprimary-primary','N2','social-habits',2,'1',1,'teaching',null,'Ceremonies in Our Culture: Marriage','["Understanding marriage: when man and woman become husband and wife", "Why people get married: to start family, love and companionship", "Marriage ceremonies: traditional and church/mosque weddings", "Marriage celebrations: decorations, food, music, dancing, guests", "Special clothes worn during weddings", "Role of bride and groom", "Children attending weddings with parents", "Understanding marriage is for adults"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,382) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t2-w2','ng-scheme-2025-preprimary-primary','N2','social-habits',2,'2',2,'teaching',null,'Ceremonies in Our Culture: Naming Ceremony','["Understanding naming ceremony: welcoming new baby and giving baby a name", "When held: usually 7-8 days after baby is born (depending on culture/religion)", "Who attends: family, friends, well-wishers", "What happens: prayers, announcing baby''s name, celebrations, gifts for baby", "Traditional practices in naming ceremonies", "Special foods and drinks served", "Importance of names and meaning of names", "Rejoicing over new life"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,382) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t2-w3','ng-scheme-2025-preprimary-primary','N2','social-habits',2,'3',3,'teaching',null,'Ceremonies in Our Culture: Festivals','["Understanding festivals: special celebrations in communities and cultures", "Types of festivals: religious festivals (Christmas, Easter, Eid-el-Fitr, Eid-el-Adha), cultural festivals (New Yam Festival, Durbar, Eyo Festival, Argungu Fishing Festival)", "Why we celebrate festivals: thanksgiving, remembrance, tradition, unity, joy", "Activities during festivals: special foods, music, dancing, wearing traditional attire, visiting family", "Learning about different cultures through festivals", "Respecting different festivals"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,382) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t2-w4','ng-scheme-2025-preprimary-primary','N2','social-habits',2,'4',4,'teaching',null,'Traditional Musical Instruments','["Understanding traditional instruments: music tools from our cultures", "Types of traditional instruments: drums (talking drum, bata drum), gong, shekere, thumb piano (molo), flute, xylophone", "How instruments are played and sounds they make", "Use in ceremonies, festivals, and traditional events", "Songs and music with traditional instruments", "Appreciating traditional music and instruments", "Differences from modern instruments"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,382) on conflict (id) do nothing;
