insert into curriculum_topics values ('N2-social-habits-t2-w7','ng-scheme-2025-preprimary-primary','N2','social-habits',2,'7',7,'teaching',null,'Traditional Rulers and Festivals','["Understanding traditional rulers: kings, emirs, obas, chiefs who lead communities", "Roles of traditional rulers: leading people, settling disputes, preserving culture, organizing festivals", "Respecting traditional rulers and their authority", "How traditional rulers connect to festivals and cultural celebrations", "Traditional attire and symbols of authority", "Palaces where traditional rulers live", "Important traditional rulers in Nigeria (examples)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,383) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t2-w8','ng-scheme-2025-preprimary-primary','N2','social-habits',2,'8',8,'teaching',null,'People in Our Country','["Understanding Nigeria is our country", "People in Nigeria: different ethnic groups (Yoruba, Igbo, Hausa, and many others)", "Unity in diversity: different languages, cultures, foods, dressing, but one nation", "Nigerian flag: green-white-green", "Living together peacefully despite differences", "Respecting all ethnic groups and cultures", "Being proud Nigerians", "National symbols and identity"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,383) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t2-w9','ng-scheme-2025-preprimary-primary','N2','social-habits',2,'9',9,'teaching',null,'Social Duties: Community Helpers','["Understanding community helpers: people who help make our community better", "Examples: teachers (help us learn), doctors/nurses (treat sick people), police officers (protect us), firefighters (put out fires), cleaners (keep environment clean), drivers (transport people), shopkeepers (sell goods)", "How each helper serves the community", "Appreciating and respecting community helpers", "Saying \"thank you\" to helpers", "Understanding everyone''s job is important"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,383) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t2-w10','ng-scheme-2025-preprimary-primary','N2','social-habits',2,'10',10,'teaching',null,'My School: People in the School','["People in school: head teacher/principal, teachers, pupils, librarian, cleaners, security guards, school nurse", "Roles of each person in school", "Head teacher: leads the school, makes important decisions", "Teachers: teach and care for pupils", "Pupils: learn, play, and obey school rules", "Support staff: help keep school running smoothly", "Respecting everyone in school", "School as our second home and learning family"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,384) on conflict (id) do nothing;
