insert into curriculum_topics values ('N2-social-habits-t3-w1','ng-scheme-2025-preprimary-primary','N2','social-habits',3,'1',1,'teaching',null,'Our Environment','["Understanding environment: everything around us (home, school, neighborhood, nature)", "Things in our environment: people, animals, plants, buildings, roads, air, water", "Clean vs dirty environment", "Importance of keeping environment clean: prevents diseases, looks beautiful, healthy living", "Ways to care for environment: not littering, using waste bins, planting trees, not destroying plants", "Environmental cleanliness at home, school, and community", "Everyone''s responsibility to protect environment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,385) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t3-w2','ng-scheme-2025-preprimary-primary','N2','social-habits',3,'2',2,'teaching',null,'Helping Others','["Importance of helping others: shows kindness, makes others happy, builds friendships", "Ways to help at home: helping parents with chores, helping siblings, tidying up", "Ways to help at school: helping classmates, sharing materials, being kind, assisting teacher", "Helping in the community: being polite to neighbors, not littering, respecting others", "Helping those in need: sharing with less privileged, showing compassion", "Understanding helping makes us feel good too", "Being a helpful and caring person"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,385) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t3-w3','ng-scheme-2025-preprimary-primary','N2','social-habits',3,'3',3,'teaching',null,'Values: Honesty and Trustworthiness','["Understanding honesty: always telling the truth, not lying", "Why honesty is important: builds trust, shows good character, makes people respect us", "Being truthful even when difficult or afraid", "Consequences of lying: people won''t trust you, punishment, guilt", "Trustworthiness: being reliable, keeping promises, doing what we say", "People trust honest children", "Examples of honest behavior", "Admitting mistakes instead of lying"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,385) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t3-w4','ng-scheme-2025-preprimary-primary','N2','social-habits',3,'4',4,'teaching',null,'Values: Responsibility and Tolerance','["Understanding responsibility: doing what we should do, taking care of duties", "Being responsible: doing homework, keeping belongings safe, following rules, helping at home", "Taking responsibility for our actions (accepting when we make mistakes)", "Understanding tolerance: accepting and respecting people who are different from us", "Tolerating differences: in opinions, cultures, abilities, appearances", "Living peacefully with others despite differences", "Not bullying or excluding others because they are different", "Patience and understanding"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,386) on conflict (id) do nothing;
