insert into curriculum_topics values ('N2-social-habits-t3-w7','ng-scheme-2025-preprimary-primary','N2','social-habits',3,'7',7,'teaching',null,'People and Their Professions','["Understanding professions: jobs people do to earn money and serve society", "Examples of professions: doctor, nurse, teacher, engineer, lawyer, farmer, driver, pilot, chef, artist, banker, soldier", "What each profession does and how they help society", "Importance of all professions: everyone contributes to society", "Respecting all professions - no job is better than another", "Understanding education helps us get good jobs", "\"What I want to be when I grow up\" - career aspirations", "Encouraging diverse career dreams"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,386) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t3-w8','ng-scheme-2025-preprimary-primary','N2','social-habits',3,'8',8,'teaching',null,'Transportation in My Neighborhood','["Understanding transportation: ways of moving from one place to another", "Vehicles commonly seen in neighborhood: cars, buses, motorcycles (okada), tricycles (keke), bicycles, trucks", "Why people use these vehicles: going to work, school, market, hospital", "Understanding different vehicles serve different purposes", "Observing transportation around us", "Road users: drivers, passengers, pedestrians", "Basic road safety: zebra crossing, traffic lights, holding adult''s hand when crossing"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,386) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t3-w9','ng-scheme-2025-preprimary-primary','N2','social-habits',3,'9',9,'teaching',null,'Means of Transportation','["Types of transportation by location: *Land transportation: cars, buses, trains, motorcycles, bicycles, trucks *Water transportation: boats, ships, canoes, ferries * Air transportation: airplanes, helicopters", "Understanding which is fastest, which carries most people", "Choosing appropriate transportation for different journeys", "Modern vs traditional means (e.g., canoe vs ship)", "Safety rules for each type of transportation", "Respecting transportation workers"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,387) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-social-habits-t3-w10','ng-scheme-2025-preprimary-primary','N2','social-habits',3,'10',10,'teaching',null,'Our Country: Nigeria','["Nigeria is our country - our home", "Location: Nigeria is in West Africa", "Nigerian flag: green-white-green (green=agriculture, white=peace)", "Capital city: Abuja", "Major cities: Lagos, Kano, Port Harcourt, Ibadan", "Languages: English (official), Hausa, Yoruba, Igbo, and many others", "Nigerian culture: diverse foods, music, dances, festivals", "Being good Nigerian citizens: obeying rules, being kind, keeping environment clean, going to school", "National pride and unity"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,387) on conflict (id) do nothing;
