insert into curriculum_topics values ('N2-civic-education-t1-w1','ng-scheme-2025-preprimary-primary','N2','civic-education',1,'1',1,'teaching',null,'Greetings','["Importance of greetings in society", "Time-appropriate greetings: Good morning, Good afternoon, Good evening, Good night", "Greetings for different people: elders, peers, teachers, parents", "Cultural greetings in local languages", "Body language in greetings: smiling, eye contact, bowing/kneeling for elders (in some cultures)", "Responding to greetings appropriately", "Greetings show respect and friendliness"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,389) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-civic-education-t1-w2','ng-scheme-2025-preprimary-primary','N2','civic-education',1,'2',2,'teaching',null,'Dressing','["Understanding appropriate dressing for different occasions", "School dressing: wearing neat school uniform properly", "Home dressing: casual, comfortable clothes", "Special occasions: traditional attire, party clothes, religious wear", "Weather-appropriate dressing: light clothes for hot weather, warm clothes for cold", "Cultural dressing: traditional Nigerian attire (agbada, iro and buba, kaftan, etc.)", "Importance of clean, neat, and modest dressing", "Respecting different dressing styles and cultures"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,389) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-civic-education-t1-w3','ng-scheme-2025-preprimary-primary','N2','civic-education',1,'3',3,'teaching',null,'Social Development: Eating','["Proper eating behavior in public and at home", "Table manners: sitting properly, using utensils correctly, chewing with mouth closed", "Washing hands before and after eating", "Saying prayers before and after meals", "Not talking with mouth full of food", "Sharing food and eating together as family or community", "Cultural eating practices: eating with right hand, communal eating", "Appreciating and not wasting food"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,389) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-civic-education-t1-w4','ng-scheme-2025-preprimary-primary','N2','civic-education',1,'4',4,'teaching',null,'Cultural Values: Helping Others','["Understanding helping as a core cultural value in African societies", "Ubuntu philosophy: \"I am because we are\" - community support", "Ways to help: at home (chores, helping siblings), at school (helping classmates), in community", "Helping elderly people: carrying loads, showing respect, listening", "Helping those in need: sharing, showing kindness, compassion", "Benefits of helping: builds community, makes everyone happy", "Cultural saying: \"A helping hand is better than a praying mouth\""]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,389) on conflict (id) do nothing;
