insert into curriculum_topics values ('N2-civic-education-t1-w7','ng-scheme-2025-preprimary-primary','N2','civic-education',1,'7',7,'teaching',null,'Cultural Values: Respect','["Understanding respect as foundation of African culture", "Respect for elders: greeting properly, not interrupting, obeying, using respectful titles", "Respect for peers: being kind, not bullying, sharing, playing fairly", "Respect for parents and teachers: listening, obeying, being polite", "Respect for cultural practices and traditions", "Respect for different cultures, religions, and beliefs", "Body language of respect: kneeling, bowing, prostrating (depending on culture)", "Understanding respect earns respect"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,390) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-civic-education-t1-w8','ng-scheme-2025-preprimary-primary','N2','civic-education',1,'8',8,'teaching',null,'Cultural Values: Folk Songs','["Understanding folk songs as part of cultural heritage", "Purpose of folk songs: teaching values, entertainment, preserving history, celebrating events", "Types of folk songs: lullabies, work songs, festival songs, moral teaching songs", "Learning simple Nigerian folk songs in local languages", "Songs that teach values: respect, hard work, honesty, unity", "Singing folk songs together as community activity", "Preserving culture through music and songs"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,390) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-civic-education-t1-w9','ng-scheme-2025-preprimary-primary','N2','civic-education',1,'9',9,'teaching',null,'Community Values','["Understanding community: group of people living together", "Ubuntu values: cooperation, sharing, caring for each other", "Community activities: market days, communal work, festivals, celebrations", "Importance of living peacefully in community", "Community support systems: neighbors helping each other", "Responsibility to community: keeping environment clean, obeying rules, being respectful", "\"It takes a village to raise a child\" - community responsibility for children"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,391) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-civic-education-t1-w10','ng-scheme-2025-preprimary-primary','N2','civic-education',1,'10',10,'teaching',null,'Cultural Activities','["Understanding cultural activities preserve traditions and heritage", "Types of cultural activities: festivals, ceremonies, traditional dances, storytelling", "Festivals: New Yam Festival, Durbar, Eyo Festival, Argungu Fishing Festival", "Traditional dances: cultural significance and occasions", "Storytelling: moonlight stories, folktales with moral lessons", "Traditional games and sports", "Importance of participating in cultural activities", "Learning from cultural activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,391) on conflict (id) do nothing;
