insert into curriculum_topics values ('N2-civic-education-t2-w1','ng-scheme-2025-preprimary-primary','N2','civic-education',2,'1',1,'teaching',null,'Cultural Activities: Practical','["Practical participation in cultural activities", "Learning and performing traditional dances", "Wearing traditional attire for cultural day", "Practicing traditional greetings and gestures", "Storytelling session: learning and telling folktales", "Playing traditional games: ayo (oware), ten-ten, boju-boju", "Singing folk songs learned previously", "Creating simple traditional crafts", "Cultural drama and role-play"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,393) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-civic-education-t2-w2','ng-scheme-2025-preprimary-primary','N2','civic-education',2,'2',2,'teaching',null,'Social Institutions','["Understanding social institutions: important organizations in society", "Family as primary social institution: where we learn first values", "School: where we learn education and social skills", "Religious institutions: churches, mosques, temples - teaching moral values", "Market: economic institution where people buy and sell", "Traditional councils: settling disputes, maintaining order", "How institutions work together for society''s benefit", "Respecting all social institutions"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,393) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-civic-education-t2-w3','ng-scheme-2025-preprimary-primary','N2','civic-education',2,'3',3,'teaching',null,'Naming Ceremony','["Understanding naming ceremony as important cultural practice", "Significance: welcoming new baby, giving identity, community celebration", "When held: 7-8 days after birth (varies by culture/religion)", "Who attends: family, friends, community members", "Activities: prayers, announcing name, giving gifts, celebrations", "Traditional practices: special foods, rituals, blessings", "Different naming ceremonies: Yoruba, Igbo, Hausa, Christian, Muslim traditions", "Understanding names have meanings and significance"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,393) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-civic-education-t2-w4','ng-scheme-2025-preprimary-primary','N2','civic-education',2,'4',4,'teaching',null,'Kinship','["Understanding kinship: family relationships and connections", "Nuclear family: father, mother, children (immediate family)", "Extended family: grandparents, uncles, aunts, cousins", "Understanding family tree and how people are related", "Kinship terms: brother, sister, cousin, nephew, niece", "Family responsibilities and support system", "Importance of family bonds and relationships", "African concept: \"blood is thicker than water\" - family loyalty"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,394) on conflict (id) do nothing;
