insert into curriculum_topics values ('N2-civic-education-t2-w7','ng-scheme-2025-preprimary-primary','N2','civic-education',2,'7',7,'teaching',null,'Chieftaincy','["Understanding chieftaincy in Nigerian traditional system", "Traditional rulers: Oba, Emir, Igwe, Obi - leaders in communities", "Roles of traditional rulers: settling disputes, preserving culture, leading community, organizing festivals", "Chieftaincy hierarchy: paramount rulers, district chiefs, village heads", "Symbols of authority: crown, staff, throne, regalia", "Respect for traditional institution and rulers", "How chieftaincy connects with modern government", "Famous traditional rulers in Nigeria"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,394) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-civic-education-t2-w8','ng-scheme-2025-preprimary-primary','N2','civic-education',2,'8',8,'teaching',null,'Religious Institutions','["Understanding religion teaches moral values and gives spiritual guidance", "Major religions in Nigeria: Christianity, Islam, Traditional religion", "Religious institutions: churches, mosques, shrines, temples", "Functions: worship, teaching values, helping community, celebrations", "Religious leaders: pastors, imams, priests, traditional priests", "Religious celebrations: Christmas, Easter, Eid-el- Fitr, Eid-el-Adha", "Respecting all religions and religious practices", "Religious tolerance and peaceful coexistence"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,394) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-civic-education-t2-w9','ng-scheme-2025-preprimary-primary','N2','civic-education',2,'9',9,'teaching',null,'Peace Education','["Understanding peace: living together without fighting or violence", "Importance of peace: in home, school, community, nation", "Ways to promote peace: being kind, sharing, forgiving, respecting others", "Conflict causes: misunderstanding, selfishness, anger, differences", "Peace values: tolerance, patience, understanding, love", "Being peacemaker: helping friends reconcile, not fighting, reporting problems to adults", "\"Peace begins with me\" - personal responsibility for peace"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,395) on conflict (id) do nothing;
