insert into curriculum_topics values ('N2-civic-education-t3-w1','ng-scheme-2025-preprimary-primary','N2','civic-education',3,'1',1,'teaching',null,'Conflict Resolution','["Understanding conflict: disagreement or fight between people", "Common conflicts among children: sharing toys, playing games, misunderstandings", "Effects of conflict: hurt feelings, broken friendships, unhappiness", "Ways to resolve conflicts: talking calmly, saying sorry, forgiving, compromising, sharing", "Role of adults in resolving conflicts", "Avoiding conflicts: being patient, taking turns, being fair", "Peaceful problem-solving skills", "Making up after conflicts"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,397) on conflict (id) do nothing;
insert into curriculum_topics values ('N2-civic-education-t3-w2','ng-scheme-2025-preprimary-primary','N2','civic-education',3,'2',2,'teaching',null,'Emotional Development: Confidence','["Understanding confidence: believing in yourself and your abilities", "Importance of confidence: helps us try new things, make friends, learn better", "Building confidence: practicing skills, accepting mistakes as learning, positive thinking", "Confident behavior: speaking up, trying activities, making eye contact", "Overcoming shyness and fear", "Encouraging words build confidence", "Understanding everyone has strengths and weaknesses", "\"I can do it\" attitude"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,397) on conflict (id) do nothing;
