insert into curriculum_topics values ('N3-literacy-letter-work-t3-w1','ng-scheme-2025-preprimary-primary','N3','literacy-letter-work',3,'1',1,'teaching',null,'Review of Sight Words and Sentence Construction','["Revision of sight words learned in second term", "Common sight words: I, a, the, is, am, and, it, in, at, on, he, she, we, me, my, to, go, no, up, can", "Additional sight words: see, look, here, there, come, have, like, play, run, jump", "Reading simple sentences using sight words", "Writing simple sentences with guidance", "Sentence structure: capital letter, spaces, full stop", "Matching sentences to pictures"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,460) on conflict (id) do nothing;
