insert into curriculum_topics values ('N3-literacy-letter-work-t3-w3','ng-scheme-2025-preprimary-primary','N3','literacy-letter-work',3,'3',3,'teaching',null,'Compound Words','["Introduction to compound words: two words joining to make one", "Simple compound words: sun + set = sunset, rain + bow = rainbow, foot + ball = football", "More examples: bedroom, classroom, breakfast, notebook, playground, outside, inside, cupcake", "Breaking compound words into parts", "Understanding meaning of compound words", "Creating own compound words", "Reading and writing compound words", "Using compound words in sentences"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,460) on conflict (id) do nothing;
