insert into curriculum_topics values ('N3-literacy-letter-work-t3-w7','ng-scheme-2025-preprimary-primary','N3','literacy-letter-work',3,'7',7,'teaching',null,'Descriptive Words (Adjectives - Simple)','["Introduction to describing words", "Color words: red, blue, green, yellow, black, white, brown, pink, orange, purple", "Size words: big, small, tall, short, long, fat, thin", "Quality words: good, bad, hot, cold, happy, sad, fast, slow", "Using describing words in sentences: \"The big dog,\" \"A red ball\"", "Matching adjectives to pictures", "Writing sentences with describing words", "Vocabulary expansion through descriptive language"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,461) on conflict (id) do nothing;
