insert into curriculum_topics values ('N3-literacy-language-domain-t1-w1','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',1,'1',1,'teaching',null,'Vowels and Consonants','["Introduction to vowels: a, e, i, o, u", "Understanding vowels as special letters", "Vowel sounds: short and long (introduction)", "Introduction to consonants: all other letters (b, c, d, f, g, h, j, k, l, m, n, p, q, r, s, t, v, w, x, y, z)", "Differentiating between vowels and consonants", "Identifying vowels and consonants in words", "Every word has at least one vowel", "Sorting activities: vowel or consonant?", "Building foundation for word formation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,464) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t1-w2','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',1,'2',2,'teaching',null,'Single Sounds: D, A, I, M','["Letter sound /d/ as in dog, doll, dad, dig", "Letter sound /a/ as in apple, ant, cat, mat (short a)", "Letter sound /i/ as in ink, insect, sit, pin (short i)", "Letter sound /m/ as in mum, man, mat, milk", "Recognizing and pronouncing each sound correctly", "Blending sounds to form words: d-a-d (dad), m-a-d (mad), d-i-m (dim)", "Writing letters d, a, i, m", "Identifying sounds at beginning, middle, and end of words", "Simple word formation using d, a, i, m"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,464) on conflict (id) do nothing;
