insert into curriculum_topics values ('N3-literacy-language-domain-t1-w7','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',1,'7',7,'teaching',null,'DIGRAPH: th, ck, wh','["Introduction to digraphs: two letters making one sound", "Digraph ''th'' (voiced and unvoiced): this, that, the, bath, with, three, think", "Sound /th/ - pronunciation and recognition", "Digraph ''ck'': back, clock, duck, pick, stick, lock, black", "Sound /ck/ as /k/ at end of words", "Digraph ''wh'': what, when, where, which, white, wheel", "Sound /wh/ pronunciation", "Reading words with th, ck, wh", "Writing digraphs and words containing them", "Identifying digraphs in words"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,465) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t1-w8','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',1,'8',8,'teaching',null,'Sight Words: The, This, They','["Sight word: The - most common word in English", "Sight word: This - recognition and usage", "Sight word: They - recognition and usage", "Notice ''th'' digraph in all three words (connecting to previous week)", "Using these sight words in sentences: \"The cat,\" \"This is me,\" \"They go\"", "Combining with previous sight words", "Reading sentences: \"This is the car,\" \"They see me,\" \"I go with them\"", "Flash card practice", "Sentence writing with new sight words", "Total sight words learned: You, Me, Her, We, I, Go, Car, The, This, They"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,466) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t1-w9','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',1,'9',9,'teaching',null,'DIGRAPH: ph, sh, ch','["Digraph ''ph'' sounds like /f/: phone, photo, elephant, graph", "Understanding ''ph'' = /f/ sound", "Digraph ''sh'': ship, shop, fish, wash, she, shell, brush", "Sound /sh/ - pronunciation and recognition", "Digraph ''ch'': chair, church, chat, chip, much, bench, lunch", "Sound /ch/ - pronunciation and recognition", "Reading words with ph, sh, ch", "Writing words containing these digraphs", "Distinguishing between different digraph sounds"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,466) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t1-w10','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',1,'10',10,'teaching',null,'Sight Words: Photo, She, Chart & Consonant Blends: Play, Fly, Greet','["Sight word: Photo (contains ''ph'' digraph)", "Sight word: She (contains ''sh'' digraph)", "Sight word: Chart (contains ''ch'' digraph)", "Connecting sight words to digraphs learned", "Introduction to consonant blends: two consonants together, each sound heard", "Blend ''pl'': play, please, plant, plus", "Blend ''fl'': fly, flag, flip, flat", "Blend ''gr'': greet, green, grab, grass", "Understanding difference between blends and digraphs", "Sight words with blends: Play, Fly, Greet", "Reading and writing words with consonant blends", "Using all new sight words in sentences"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,466) on conflict (id) do nothing;
