insert into curriculum_topics values ('N3-literacy-language-domain-t2-w1','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',2,'1',1,'teaching',null,'Capital Letters','["Review of capital letters A-Z", "Understanding when to use capital letters: at the beginning of sentences, for names (people, places), for the word \"I\"", "Practicing capital letter formation", "Identifying capital letters in words and sentences", "Converting lower case to upper case and vice versa", "Writing names with capital letters: own name, friends'' names, family members", "Writing sentences with correct capitalization", "Days of the week (introduction): Monday, Tuesday, etc. start with capitals", "Months of the year (introduction): January, February, etc. start with capitals"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,469) on conflict (id) do nothing;
