insert into curriculum_topics values ('N3-literacy-language-domain-t2-w3','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',2,'3',3,'teaching',null,'Double Consonants','["Introduction to double consonants: two same consonants together", "Common double consonants: bb, dd, ff, gg, ll, mm, nn, pp, rr, ss, tt, zz", "Examples: rabbit, ladder, off, egg, bell, summer, dinner, happy, purr, dress, butter, buzz", "Understanding double consonants often come after short vowels", "Pronunciation: double consonants make one sound", "Reading words with double consonants", "Writing words with double consonants", "Identifying double consonants in words", "Word building activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,469) on conflict (id) do nothing;
