insert into curriculum_topics values ('N3-literacy-language-domain-t2-w7','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',2,'7',7,'teaching',null,'ALTERNATIVE SPELLINGS (Part 1): ai/ae/ay and ee/ea','["Introduction to alternative spellings: different letter combinations making same sound", "Long ''a'' sound /ay/: ai (rain, train, mail), ae (aerobics - less common), ay (play, day, say, tray)", "Understanding ai usually in middle of words, ay at end", "Long ''e'' sound /ee/: ee (tree, bee, see, feet, sleep), ea (eat, sea, tea, read, dream)", "Recognizing same sound, different spelling", "Reading words with alternative spellings", "Spelling practice: choosing correct pattern", "Word families: rain/train, play/say, tree/see, tea/sea", "Using words in sentences"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,470) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t2-w8','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',2,'8',8,'teaching',null,'ALTERNATIVE SPELLINGS (Part 2): igh/y/ie, oi/oy, ou/ow + SIGHT WORDS: Be, Was, Like, Here','["Long ''i'' sound /eye/: igh (high, night, light, right), y (my, fly, cry, try), ie (tie, pie, lie) -/oy/ sound: oi (oil, coin, boil, soil), oy (boy, toy, joy, enjoy) - /ow/ sound: ou (out, shout, house, mouse), ow (cow, how, now, brown)", "Understanding position rules: oi in middle, oy at end; ou in middle, ow at end", "Reading and spelling words with alternative patterns", "Sight word: Be - recognition and usage", "Sight word: Was - past tense of \"is/am\"", "Sight word: Like - recognition and usage", "Sight word: Here - recognition and usage", "Using new sight words in sentences"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,471) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t2-w9','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',2,'9',9,'teaching',null,'TRIGRAPHS: are, air, tch, ure + SIGHT WORDS: Hair, Match, Pure','["Introduction to trigraphs: three letters making one sound", "Trigraph ''are'' /air/: care, share, dare, bare, square", "Trigraph ''air'' /air/: hair, fair, pair, chair, stairs", "Understanding ''are'' and ''air'' make same sound", "Trigraph ''tch'' /ch/: catch, match, watch, kitchen, pitch (comes after short vowel)", "Trigraph ''ure'' /oor/ or /yoor/: pure, cure, sure, picture, nature", "Reading words with trigraphs", "Sight word: Hair (contains ''air'' trigraph)", "Sight word: Match (contains ''tch'' trigraph)", "Sight word: Pure (contains ''ure'' trigraph)", "Connecting sight words to trigraphs", "Writing and spelling practice"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,471) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t2-w10','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',2,'10',10,'teaching',null,'ARTICLES: THE USE OF ''a'', ''an'' AND ''some'' + SIGHT WORDS: There, Live, Four, Do, They, Give','["Review of article ''a'': used before consonant sounds (a cat, a dog, a book)", "Review of article ''an'': used before vowel sounds (an apple, an egg, an orange)", "Article ''some'': used with plural nouns or uncountable nouns (some eggs, some water)", "Choosing correct article: a/an/some", "Practice exercises with articles", "Sight word: There - recognition and usage (different from \"their\")", "Sight word: Live - recognition and usage", "Sight word: Four - number word", "Sight word: Do - recognition and usage", "Sight word: They - recognition and usage (review)", "Sight word: Give - recognition and usage", "Using articles and sight words in sentences: \"Give me an egg,\" \"They live there,\" \"Do we have some?\"", "Sentence construction with articles"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,472) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t2-w11','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',2,'11',11,'revision',null,'Revision of Second Term Work','["Capital letters comprehensive review", "All sight words review: One, We, Some, Egg, Add, Ink, Comb, Be, Was, Like, Here, Hair, Match, Pure, There, Live, Four, Do, They, Give (20+ sight words)", "Double consonants revision", "Alternative spellings review: ai/ae/ay, ee/ea, igh/y/ie, oi/oy, ou/ow", "Trigraphs review: are, air, tch, ure", "Articles usage practice: a, an, some", "Reading fluency with all learned patterns", "Sentence writing with correct capitalization, sight words, and articles", "Mock examination exercises", "Identifying areas needing reinforcement"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,472) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t2-w12','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',2,'12',12,'examination',null,'End of Term Examination','["Capital letters usage test", "Writing sentences with correct capitalization", "All sight words recognition and writing test (20+ words)", "Double consonants identification and spelling", "Alternative spellings comprehensive test", "Reading words with ai/ay, ee/ea, igh/y/ie, oi/oy, ou/ow", "Trigraphs reading and spelling assessment", "Articles usage test: choosing a, an, or some correctly", "Sentence reading fluency evaluation", "Sentence construction and writing test", "Word dictation using learned patterns", "Oral reading and pronunciation assessment", "Overall language domain progress evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,473) on conflict (id) do nothing;
