insert into curriculum_topics values ('N3-literacy-language-domain-t3-w1','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',3,'1',1,'teaching',null,'Reading Review: Blends, Digraphs, Trigraphs + Sight Words: Shirt, Clock, Hair','["Comprehensive review of consonant blends: bl, cl, fl, gl, pl, sl, br, cr, dr, fr, gr, pr, tr, sc, sk, sm, sn, sp, st, sw", "Reading words with blends: flag, trip, skip, plant, green, dress", "Review of digraphs: th, ck, wh, ph, sh, ch", "Reading words with digraphs: shop, when, match, phone", "Review of trigraphs: are, air, tch, ure", "Reading words with trigraphs: chair, catch, pure, share", "Sight word: Shirt (contains ''sh'' digraph and ''ir'' pattern)", "Sight word: Clock (contains ''ck'' digraph and ''cl'' blend)", "Sight word: Hair (contains ''air'' trigraph - review)", "Connecting sight words to phonics patterns", "Reading sentences with blends, digraphs, and trigraphs", "Fluency practice with mixed patterns"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,473) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t3-w2','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',3,'2',2,'teaching',null,'Introduction to Nouns + Sight Words: Old, Should, Young','["Understanding nouns: naming words for people, places, things, animals", "Common nouns: people (boy, girl, teacher, man, woman), places (school, home, park, shop), things (book, pen, car, chair), animals (dog, cat, bird, fish)", "Proper nouns: names of specific people and places (always start with capital letters)", "Identifying nouns in sentences", "Sorting words: noun or not a noun?", "Singular and plural nouns (simple): cat/cats, book/books", "Sight word: Old - recognition and usage (can describe nouns: \"old man\")", "Sight word: Should - recognition and usage", "Sight word: Young - recognition and usage (opposite of old: \"young girl\")", "Using describing words with nouns: old man, young boy", "Writing sentences with nouns"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,474) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t3-w3','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',3,'3',3,'teaching',null,'Introduction to Verbs + Sight Words: Upon, Little, What','["Understanding verbs: action/doing words", "Common action verbs: run, jump, walk, sit, eat, drink, sleep, play, read, write, sing, dance", "More verbs: swim, fly, hop, skip, catch, throw, kick, clap", "Identifying verbs in sentences", "Understanding that verbs tell what someone/something does", "Acting out verbs for better understanding", "Present tense verbs: I run, She jumps, They play", "Sight word: Upon - recognition and usage (similar to \"on\")", "Sight word: Little - recognition and usage (describes size: \"little cat\")", "Sight word: What - question word, recognition and usage", "Using verbs in sentences: \"What do you do?\" \"I jump\"", "Writing sentences with action verbs"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,474) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t3-w4','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',3,'4',4,'teaching',null,'Nouns and Verbs Combined + Sight Words: Yellow, There, Your','["Understanding that sentences need both nouns and verbs", "Sentence pattern: Noun + Verb (The dog runs, The girl jumps)", "Identifying nouns and verbs in sentences", "Matching nouns to appropriate verbs: bird/flies, fish/swims, teacher/teaches", "Creating sentences with nouns and verbs", "Understanding subject (who/what) and action (what they do)", "Sight word: Yellow - color word, recognition and usage", "Sight word: There - recognition and usage (review)", "Sight word: Your - possessive word, recognition and usage", "Using all word types together: \"Your yellow bird flies\"", "Sentence construction practice", "Writing complete sentences with nouns and verbs"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,475) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t3-w5','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',3,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Blends, digraphs, and trigraphs reading test", "Sight words recognition: Shirt, Clock, Hair, Old, Should, Young, Upon, Little, What, Yellow, There, Your (12 new words)", "Sight words writing assessment", "Nouns identification test: recognizing naming words", "Verbs identification test: recognizing action words", "Distinguishing nouns from verbs", "Sentence reading with nouns and verbs", "Simple sentence construction test", "Using sight words in sentences", "Oral reading fluency evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,475) on conflict (id) do nothing;
