insert into curriculum_topics values ('N3-literacy-language-domain-t3-w7','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',3,'7',7,'teaching',null,'Sentence Construction with Nouns and Verbs + Sight Words: Because, Them, Put','["Advanced sentence patterns: Noun + Verb + Noun (The boy kicks the ball)", "Using describing words in sentences: The big dog runs fast", "Compound sentences (simple): I run and I jump", "Understanding word order in sentences", "Expanding sentences with more details", "Questions and statements with nouns and verbs: \"What does the cat do?\" \"The cat sleeps\"", "Sight word: Because - conjunction, showing reason", "Sight word: Them - pronoun, recognition and usage", "Sight word: Put - verb, recognition and usage", "Using \"because\" to extend sentences: \"I sleep because I am tired\"", "Practice with pronouns replacing nouns: The boys → them", "Writing longer, more complex sentences", "Punctuation review: capital letters, full stops, question marks"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,475) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t3-w8','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',3,'8',8,'teaching',null,'Advanced Reading Practice','["Reading simple stories with familiar phonics patterns", "Comprehension: understanding what is read", "Answering questions about stories: Who? What? Where? When? Why?", "Identifying main characters and events in stories", "Finding nouns and verbs in story texts", "Locating sight words in reading passages", "Reading with expression and fluency", "Retelling stories in own words", "Predicting what happens next in stories", "Making connections between stories and personal experiences", "Drawing pictures about stories read", "Discussing favorite parts of stories"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,476) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t3-w9','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',3,'9',9,'teaching',null,'Creative Writing and Expression + Sight Words: Their, Want, Once','["Writing own simple stories using learned words", "Story structure: beginning, middle, end", "Using nouns and verbs in creative writing", "Adding describing words to make stories interesting", "Writing about personal experiences: \"What I did,\" \"My family,\" \"My favorite toy\"", "Using sight words in writing", "Sight word: Their - possessive pronoun (different from \"there\")", "Sight word: Want - verb, expressing desire", "Sight word: Once - time word, used in storytelling (\"Once upon a time\")", "Understanding homophones: there/their", "Using \"once\" to start stories", "Writing sentences: \"They want their toys,\" \"Once I saw...\"", "Sharing written work with classmates", "Building confidence in independent writing"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,476) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t3-w10','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',3,'10',10,'teaching',null,'Comprehensive Reading, Writing and Grammar','["Integration of all skills learned: phonics, sight words, nouns, verbs, sentence construction", "Reading passages with mixed phonics patterns", "Identifying all parts of sentences: nouns, verbs, describing words, sight words", "Writing complete, grammatically correct sentences", "Using capital letters, full stops, question marks correctly", "Proofreading own work for errors", "Reading own writing to others", "Answering comprehension questions about passages read", "Vocabulary development through reading", "Understanding context clues in reading", "Expressing ideas clearly in writing", "Building reading stamina with longer texts"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,477) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t3-w11','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',3,'11',11,'revision',null,'Revision of Third Term & Year''s Work','["Third Term Review:", "Blends, digraphs, trigraphs comprehensive practice", "All third term sight words: Shirt, Clock, Hair, Old, Should, Young, Upon, Little, What, Yellow, There, Your, Because, Them, Put, Their, Want, Once (18 new words)", "Nouns and verbs identification and usage", "Sentence construction with proper grammar", "Reading comprehension practice", "Creative writing review Year-Long Comprehensive Review:", "Complete alphabet and letter sounds", "All phonics patterns: single sounds, blends, digraphs, trigraphs, alternative spellings", "Complete sight word vocabulary (50+ words from all three terms)", "Parts of speech: nouns, verbs, articles, describing words", "Capitalization and punctuation rules", "Sentence reading and construction", "Story comprehension", "Creative writing", "Mock examination exercises", "Reading fluency practice"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,477) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-literacy-language-domain-t3-w12','ng-scheme-2025-preprimary-primary','N3','literacy-language-domain',3,'12',12,'examination',null,'End of Year Examination','["Third Term Assessment:", "Reading test: blends, digraphs, trigraphs in words and sentences", "Sight words comprehensive test (all third term words)", "Nouns identification and usage test", "Verbs identification and usage test", "Grammar test: combining nouns and verbs correctly", "Sentence construction assessment", "Reading comprehension test with questions", "Creative writing assessment Comprehensive Year Assessment:", "Complete phonics mastery test (all patterns learned)", "All sight words recognition (50+ words from three terms)", "Reading fluency evaluation", "Grammar comprehensive test (nouns, verbs, articles, capitalization, punctuation)", "Sentence writing with proper structure", "Story reading comprehension", "Independent writing assessment", "Oral reading and pronunciation", "Overall Nursery 3 Literacy mastery evaluation", "Readiness for Primary 1 literacy assessment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,478) on conflict (id) do nothing;
