insert into curriculum_topics values ('N3-numeracy-t2-w7','ng-scheme-2025-preprimary-primary','N3','numeracy',2,'7',7,'teaching',null,'Numbers 1-200','["Recognition of figures 1-200 (milestone!)", "Counting orally from 1-200", "Counting objects from 1-200", "Tracing and writing figures 1-200", "Reading figures written in words: one hundred and ninety-one to two hundred", "Understanding 200 as 2 hundreds or 20 tens", "Comprehensive number work 1-200", "Celebrating the achievement of counting to 200"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,484) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-numeracy-t2-w8','ng-scheme-2025-preprimary-primary','N3','numeracy',2,'8',8,'teaching',null,'Ordinal Numbers: 1st - 10th','["Introduction to ordinal numbers (showing position or order)", "Writing and reading ordinal numbers: 1st, 2nd, 3rd, 4th, 5th, 6th, 7th, 8th, 9th, 10th", "Reading ordinal words: first, second, third, fourth, fifth, sixth, seventh, eighth, ninth, tenth", "Using ordinal numbers in real-life contexts: position in line, floors in building, days of month", "Identifying positions: who is first? who is fifth?", "Understanding difference between cardinal (counting) and ordinal (position) numbers"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,484) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-numeracy-t2-w9','ng-scheme-2025-preprimary-primary','N3','numeracy',2,'9',9,'teaching',null,'Ordering of Numbers: Descending and Ascending Order','["Understanding ascending order: arranging from smallest to largest (1, 2, 3, 4, 5...)", "Practicing ascending order with numbers 1-50, 1-100, 1-200", "Understanding descending order: arranging from largest to smallest (10, 9, 8, 7...)", "Practicing descending order with various number sets", "Comparing numbers: greater than, less than", "Ordering three or more numbers", "Finding smallest and largest in a group of numbers", "Number line activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,484) on conflict (id) do nothing;
