insert into curriculum_topics values ('N3-numeracy-t3-w2','ng-scheme-2025-preprimary-primary','N3','numeracy',3,'2',2,'teaching',null,'Greater Than and Less Than: Numbers 1-30','["Introduction to comparison symbols: > (greater than), < (less than), = (equal to)", "Understanding \"greater than\" means bigger or more", "Understanding \"less than\" means smaller or fewer", "Comparing numbers 1-30 using symbols", "Identifying which number is greater: 15 > 12", "Identifying which number is less: 8 < 20", "Finding equal numbers: 25 = 25", "Practical comparison activities with objects"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,486) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-numeracy-t3-w3','ng-scheme-2025-preprimary-primary','N3','numeracy',3,'3',3,'teaching',null,'Greater Than and Less Than: Numbers 1-50','["Extending comparison to numbers 1-50", "Using >, <, = symbols with larger numbers", "Comparing two-digit numbers: 45 > 32, 28 < 41", "Understanding comparison based on place value", "Comparing tens first, then ones", "Ordering three numbers using comparison", "Word problems involving comparison", "Games and activities with greater than/less than"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,486) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-numeracy-t3-w4','ng-scheme-2025-preprimary-primary','N3','numeracy',3,'4',4,'teaching',null,'Place Values of Numbers: 1-99 (Tens and Units)','["Understanding place value system", "Identifying tens place and ones/units place", "Understanding 45 = 4 tens and 5 ones", "Breaking down numbers into tens and ones: 67 = 6 tens + 7 ones = 60 + 7", "Building numbers from tens and ones", "Expanded form: 82 = 80 + 2", "Comparing numbers using place value", "Understanding value of digits based on position", "Place value games and activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,486) on conflict (id) do nothing;
