insert into curriculum_topics values ('N3-numeracy-t3-w7','ng-scheme-2025-preprimary-primary','N3','numeracy',3,'7',7,'teaching',null,'Length Measurement','["Introduction to measurement concept", "Understanding length: how long or short something is", "Comparing lengths: longer, shorter, same length", "Non-standard units of measurement: using hands, feet, pencils to measure", "Introduction to standard units: centimeter (cm), meter (m)", "Using rulers to measure objects (simple)", "Measuring classroom objects", "Ordering objects by length: shortest to longest", "Estimating and measuring lengths"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,487) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-numeracy-t3-w8','ng-scheme-2025-preprimary-primary','N3','numeracy',3,'8',8,'teaching',null,'Simple Addition of Numbers (Sum Less Than 20)','["Review of addition concept: putting together, combining", "Addition symbol: + (plus) and = (equals)", "Addition facts within 10: 3+2=5, 4+5=9", "Addition facts within 20: 8+7=15, 9+6=15", "Using number line for addition", "Addition with objects and pictures", "Vertical and horizontal addition", "Word problems: \"I have 7 apples and get 5 more. How many do I have?\"", "Commutative property: 5+3 = 3+5"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,487) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-numeracy-t3-w9','ng-scheme-2025-preprimary-primary','N3','numeracy',3,'9',9,'teaching',null,'Simple Subtraction of Numbers (Not More Than 20)','["Review of subtraction concept: taking away, removing", "Subtraction symbol:", "(minus)", "Subtraction facts within 10: 8-3=5, 9-4=5", "Subtraction facts within 20: 15-7=8, 18-9=9", "Using number line for subtraction (counting backwards)", "Subtraction with objects", "Relating addition and subtraction: 8+5=13, so 13-5=8", "Word problems: \"I have 12 sweets and eat 5. How many are left?\"", "Missing number problems"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,487) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-numeracy-t3-w10','ng-scheme-2025-preprimary-primary','N3','numeracy',3,'10',10,'teaching',null,'Simple Addition and Subtraction Using Place Values & Money: N1-n30','["Using place value understanding in addition and subtraction", "Adding tens and ones separately: 23+14 = (20+10) + (3+4) = 37", "Subtracting using place value understanding", "Introduction to Nigerian currency: Naira (₦) and Kobo (k)", "Recognizing coins and notes: ₦1, ₦2, ₦5, ₦10, ₦20, ₦50 (up to ₦30 for this level)", "Counting money: ₦5 + ₦10 = ₦15", "Simple addition with money: ₦12 + ₦8 = ₦20", "Simple subtraction with money: ₦25 - ₦10 = ₦15", "Shopping role-play and money activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,488) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-numeracy-t3-w11','ng-scheme-2025-preprimary-primary','N3','numeracy',3,'11',11,'revision',null,'Revision of Third Term & Year''s Work','["Third Term Review:", "Greater than and less than (1-50)", "Place value (tens and ones)", "Length measurement", "Addition and subtraction (within 20)", "Addition and subtraction using place values", "Money (₦1-₦30) Year-Long Comprehensive Review:", "Numbers 1-200 mastery", "Odd and even numbers", "Time, days, months", "Shapes", "Roman numerals", "Ordinal numbers", "Ascending and descending order", "Fractions (1/2, 1/3)", "All operations and measurements", "Mock examination exercises"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,488) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-numeracy-t3-w12','ng-scheme-2025-preprimary-primary','N3','numeracy',3,'12',12,'examination',null,'End of Year Examination','["Third Term Assessment:", "Comparison test (>, <, =)", "Place value comprehensive test", "Length measurement assessment", "Addition facts test (within 20)", "Subtraction facts test (within 20)", "Place value addition and subtraction", "Money recognition and calculation Comprehensive Year Assessment:", "Numbers 1-200 complete mastery", "All number concepts (odd/even, ordinal, fractions)", "Time and shapes", "Roman numerals", "Ordering numbers", "All mathematical operations", "Measurement and money", "Overall Nursery 3 numeracy mastery", "Readiness for Primary 1 mathematics"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,488) on conflict (id) do nothing;
