insert into curriculum_topics values ('N3-basic-science-and-technology-t1-w1','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',1,'1',1,'teaching',null,'Our Body','["Understanding the human body", "Major external body parts: head, neck, trunk, arms, legs", "Parts of the head: eyes, nose, ears, mouth, hair", "Parts of the trunk: chest, stomach, back, waist", "Parts of the limbs: shoulders, elbows, wrists, hands, fingers, hips, knees, ankles, feet, toes", "Functions of major body parts", "Understanding our body is special and unique", "Body awareness activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,490) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t1-w2','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',1,'2',2,'teaching',null,'Care for Our Body','["Importance of body care for health and wellbeing", "Daily body care practices: bathing/washing regularly, brushing teeth twice daily, washing hands frequently", "Hair care: washing, combing, keeping neat", "Nail care: keeping short and clean", "Wearing clean clothes daily", "Eating healthy food and drinking clean water", "Getting enough sleep and rest", "Exercising and playing for strong, healthy body", "Regular health check-ups"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,490) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t1-w3','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',1,'3',3,'teaching',null,'First Aid: First Aid Box Contents','["Understanding first aid: immediate help given to injured or sick person", "Introduction to first aid box/kit", "Contents of first aid box: plasters/band-aids, bandages, cotton wool, antiseptic liquid/cream, scissors, thermometer, safety pins, gloves", "Other items: pain relief medicine, gauze, tape, tweezers", "Importance of having first aid box at home and school", "Only adults should use first aid box items", "Keeping first aid box clean and well-stocked"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,490) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t1-w4','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',1,'4',4,'teaching',null,'First Aid: Uses','["Uses of first aid box items", "Plasters/band-aids: covering small cuts and scrapes", "Bandages: wrapping wounds, supporting sprains", "Cotton wool: cleaning wounds, applying medicine", "Antiseptic: cleaning wounds to prevent infection", "Thermometer: checking body temperature", "Understanding when to call for adult help", "Knowing emergency numbers (with adult supervision)", "Importance of staying calm during emergencies"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,490) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t1-w5','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',1,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Body parts identification test", "Body care practices assessment", "First aid box contents identification", "Uses of first aid items test", "Safety and health awareness evaluation", "Oral questions on topics covered"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,491) on conflict (id) do nothing;
