insert into curriculum_topics values ('N3-basic-science-and-technology-t1-w7','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',1,'7',7,'teaching',null,'Body Care for Wounds: Meaning, Causes & Types','["Understanding wounds: injuries that break the skin", "Causes of wounds: cuts from sharp objects, falls and scrapes, burns, insect bites, animal scratches", "Types of wounds: cuts (from knives, glass, sharp objects), scrapes/grazes (from falling), bruises (from bumping), burns (from hot objects), punctures (from nails, thorns)", "Preventing wounds: being careful with sharp objects, not running in dangerous areas, staying away from hot things", "Understanding some wounds are minor, some need doctor''s care"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,491) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t1-w8','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',1,'8',8,'teaching',null,'Body Care for Wounds: Care for Wounds','["First aid for minor wounds: wash hands first, clean wound with clean water, apply antiseptic, cover with plaster or bandage", "When to call adult immediately: deep cuts, heavy bleeding, large burns, animal bites, puncture wounds", "Never touch wounds with dirty hands", "Don''t pick at scabs (let them heal naturally)", "Change bandages regularly", "Watch for signs of infection: redness, swelling, pus", "Understanding healing takes time", "Prevention is better than treatment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,491) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t1-w9','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',1,'9',9,'teaching',null,'Sickness: Definition, Types and Symptoms','["Understanding sickness/illness: when body is not working properly, feeling unwell", "Common childhood sicknesses: cold/cough, fever, stomach ache, headache, malaria, diarrhea, measles, chicken pox", "Symptoms (signs of sickness): fever/high temperature, pain, coughing, sneezing, vomiting, weakness, loss of appetite, rashes", "Understanding symptoms tell us something is wrong", "Telling adults when feeling unwell", "Thermometer use for checking fever"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,492) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t1-w10','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',1,'10',10,'teaching',null,'Sickness: Causes and Care for the Sick','["Causes of sickness: germs (bacteria, viruses), dirty water/food, mosquito bites, not eating well, not sleeping enough, cold weather", "Preventing sickness: washing hands, eating healthy food, drinking clean water, covering mouth when coughing, sleeping under mosquito net", "Care for sick people: rest and sleep, taking medicine as prescribed by doctor, drinking plenty of fluids, eating nutritious food, staying warm", "Visiting doctor when sick", "Being kind to sick people", "Understanding sickness is temporary, we get better"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,492) on conflict (id) do nothing;
