insert into curriculum_topics values ('N3-basic-science-and-technology-t2-w1','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',2,'1',1,'teaching',null,'Rocks and Soil','["Rocks:", "Definition of rocks: hard, solid materials found naturally on earth", "Formation of rocks: from cooling lava, compressed sediments, changed by heat and pressure", "Types of rocks (simple): big rocks, small stones, pebbles, sand", "Uses of rocks: building houses, making roads, decoration, tools Soil:", "Definition of soil: top layer of earth where plants grow", "Formation of soil: from broken down rocks, dead plants and animals", "Types of soil: sandy soil (grainy, drains quickly), clay soil (sticky when wet, smooth), loamy soil (mixture, best for plants)", "Importance of soil: plants grow in it, animals live in it, provides food"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,493) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t2-w2','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',2,'2',2,'teaching',null,'Food: Definition and Why People Eat','["Definition of food: anything we eat or drink that gives our body energy and helps us grow", "Why people eat food: to get energy for work and play, to grow tall and strong, to stay healthy and fight sickness, to repair body when injured, to feel satisfied and happy", "Understanding all living things need food", "Different people eat different foods (cultural diversity)", "Three main meals: breakfast, lunch, dinner", "Healthy snacks between meals"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,493) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t2-w3','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',2,'3',3,'teaching',null,'Food: Types and Sources','["Types of food by function: *Energy-giving foods (carbohydrates): rice, yam, bread, cassava, potatoes, sugar * Body-building foods (proteins): meat, fish, eggs, beans, milk, cheese *Protective foods (vitamins and minerals): fruits, vegetables, milk", "Sources of food: * Plant sources: fruits, vegetables, grains, nuts * Animal sources: meat, fish, eggs, milk", "Understanding balanced diet: eating variety of foods", "Eating fruits and vegetables daily", "Drinking plenty of water"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,494) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t2-w4','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',2,'4',4,'teaching',null,'Living Things: Meaning and Characteristics','["Meaning of living things: things that have life", "Examples of living things: humans, animals, plants, insects, birds, fish", "Characteristics of living things: * Movement: they can move or parts move * Growth: they grow bigger and change * Nutrition: they need food/water * Respiration: they breathe/take in air *Reproduction: they can have babies/young ones * Sensitivity: they respond to surroundings * Excretion: they remove waste", "Difference from non-living things: stones, water, chairs don''t have these characteristics", "Observing living things around us"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,494) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t2-w5','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',2,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Rocks and soil knowledge test", "Food types and sources assessment", "Why we eat food evaluation", "Living things identification test", "Characteristics of living things assessment", "Oral questions and practical observations"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,494) on conflict (id) do nothing;
