insert into curriculum_topics values ('N3-basic-science-and-technology-t2-w7','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',2,'7',7,'teaching',null,'Growth in Animals','["Understanding growth: change from small to big over time", "Animal life cycles: baby → young → adult", "Examples of growth in animals: * Humans: baby → child → teenager → adult * Chickens: egg → chick → hen/rooster * Dogs: puppy → adult dog * Cats: kitten → adult cat * Frogs: egg → tadpole → froglet → frog * Butterflies: egg → caterpillar → chrysalis → butterfly", "Changes during growth: size increases, features develop, ability to reproduce", "Understanding growth needs: food, water, air, shelter", "Observing growth in pets or animals around"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,494) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t2-w8','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',2,'8',8,'teaching',null,'Growth in Plants','["Understanding plant growth: change from seed to mature plant", "Plant life cycle: seed → germination → seedling → young plant → mature plant → produces seeds", "What plants need to grow: water, sunlight, air, soil/nutrients, space", "Stages of plant growth: seed planted in soil, roots grow down, shoot grows up, leaves develop, stem becomes stronger, flowers bloom, fruits form, seeds produced", "Changes during growth: size increases, more leaves, flowers appear, produces fruits", "Simple plant growing experiment: planting beans/seeds", "Caring for growing plants"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,495) on conflict (id) do nothing;
